notes are \\setstretch{1.5}\n\\setlength{\\footnotemargin}{1mm}\n\n\n\\allowdisplaybreaks\n\n\\newcommand\\spacingset[1]{\\renewcommand{\\baselinestretch}%\n{#1}\\small\\normalsize}\n\n%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%\n\n%% === submission\n\\newcommand{\\blind}{1}\n\n\\def\\letas{\\mathrel{\\mathop{=}\\limits^{\\triangle}}}\n\n\\newcommand*{\\QEDB}{\\hfill\\ensuremath{\\square}}\n\\newcommand{\\SimDateOne}{2022DASH09DASH30}\n\\newcommand{\\SimDateTwo}{2022DASH08DASH10}\n\\newcommand{\\red}{\\color{red}}\n\\newcommand{\\blue}{\\color{blue}}\n\\newcommand{\\Beta}{\\textsf{Beta}}\n\\newcommand{\\Binomial}{\\text{Binomial}}\n\\newcommand{\\Bern}{\\textsf{Bernoulli}}\n\\newcommand{\\Expo}{\\textsf{Expo}}\n\\newcommand{\\Pois}{\\textsf{Pois}}\n\\newcommand{\\Unif}{\\textsf{Uniform}}\n\\newcommand{\\Normal}{\\mathcal{N}}\n\\newcommand{\\Gammad}{\\textsf{Gamma}}\n\\newcommand{\\logit}{\\text{logit}}\n\\newcommand{\\expit}{\\text{expit}}\n\\newcommand{\\mexpit}{\\text{mexpit}}\n\\newcommand{\\Dir}{\\textsf{Dirichlet}}\n\\newcommand{\\Multi}{\\textsf{Multi}}\n\\newcommand{\\Cat}{\\textsf{Categorical}}\n\n\\newcommand{\\pr}{\\text{pr}}\n\\newcommand{\\Var}{\\textrm{Var}}\n\\newcommand{\\Cov}{\\text{Cov}}\n\\newcommand{\\softmax}{\\textrm{softmax}}\n\\newcommand{\\sumN}{\\sum_{i=1}^N}\n\\newcommand{\\wt}{\\widetilde}\n\n\\newcommand{\\Prr}{\\textrm{Pr}}\n\\newcommand{\\E}{\\mathbb{E}}\n\\newcommand{\\bX}{\\mathbf{X}}\n\\newcommand{\\bx}{\\mathbf{x}}\n\\newcommand{\\bW}{\\mathbf{W}}\n\\newcommand{\\bw}{\\mathbf{w}}\n\\newcommand{\\bs}{\\mathbf{s}}\n\\newcommand{\\bc}{\\mathbf{c}}\n\\newcommand{\\bI}{\\mathbf{I}}\n\\newcommand{\\bZero}{\\mathbf{0}}\n\\newcommand{\\bM}{\\mathbf{M}}\n\\newcommand{\\bo}{\\mathbf{o}}\n\\newcommand{\\bO}{\\mathbf{O}}\n\\newcommand{\\SoftPlus}{\\textrm{SoftPlus}}\n\\newcommand{\\Sigmoid}{\\textrm{Sigmoid}}\n\\newcommand{\\InvSoftMax}{\\textrm{InvSoftMax}}\n\\newcommand{\\InvSoftPlus}{\\textrm{InvSoftPlus}}\n\\newcommand",
    "{\\InvSigmoid}{\\textrm{InvSigmoid}}\n\\newcommand{\\InvSoftMax}{\\textrm{InvSoftMax}}\n\\newcommand{\\bQ}{\\mathbf{Q}}\n\\newcommand{\\bV}{\\mathbf{V}}\n\\newcommand{\\bU}{\\mathbf{U}}\n\\newcommand{\\bu}{\\mathbf{u}}\n\\newcommand{\\bp}{\\textbf{p}}\n\\newcommand{\\bP}{\\textbf{P}}\n\\newcommand{\\ATE}{\\textsf{ATE}}\n\\newcommand{\\bepsilon}{\\bm{\\epsilon}}\n\\newcommand{\\boldeta}{\\bm{\\eta}}\n\\newcommand{\\Dist}[1]{\\textrm{#1}}\n\\newcommand{\\Evolve}[1]{\\frac{\\textrm{d}#1}{\\textrm{d}t}}\n\\newcommand{\\bpi}{\\boldsymbol{\\pi}}\n\\newcommand{\\bPi}{\\boldsymbol{\\Pi}}\n\\newcommand{\\gst}{g_{\\textrm{s.t.}}}\n\\newcommand{\\balpha}{\\boldsymbol{\\alpha}}\n\\newcommand{\\btheta}{\\boldsymbol{\\theta}}\n\\newcommand{\\bTheta}{\\boldsymbol{\\Theta}}\n\\newcommand{\\bgamma}{\\boldsymbol{\\gamma}}\n\\newcommand{\\ob}{^\\textrm{Obs}}\n\\newcommand{\\bv}{\\mathbf{v}}\n\\newcommand{\\bC}{\\mathbf{C}}\n\\newcommand{\\bz}{\\mathbf{z}}\n\\newcommand{\\bZ}{\\mathbf{Z}}\n\\newcommand{\\bY}{\\mathbf{Y}}\n\\newcommand{\\by}{\\mathbf{y}}\n\\newcommand{\\dd}{\\textrm{d}}\n\\newcommand{\\bT}{\\mathbf{T}}\n\\newcommand{\\bt}{\\mathbf{t}}\n\n\\newcommand{\\bA}{\\bm{A}}\n\\newcommand{\\ba}{\\bm{a}}\n\\newcommand{\\bh}{\\bm{h}}\n\\newcommand{\\bD}{\\bm{D}}\n\\newcommand{\\bd}{\\bm{d}}\n\\newcommand{\\bd}{\\bm{d}}\n\\newcommand{\\cI}{\\mathcal{I}}\n\\newcommand{\\cL}{\\mathcal{L}}\n\\newcommand{\\cU}{\\mathcal{U}}\n\\newcommand{\\cW}{\\mathcal{W}}\n\\newcommand{\\cV}{\\mathcal{V}}\n\\newcommand{\\cZ}{\\mathcal{Z}}\n\\newcommand{\\cD}{\\mathcal{D}}\n\\newcommand{\\oD}{\\overline{D}}\n\\newcommand{\\oY}{\\overline{Y}}\n\\newcommand{\\bone}{\\mathbf{1}}\n\n\\newcommand{\\bbeta}{\\boldsymbol{\\beta}}\n\\newcommand{\\bsigma}{\\boldsymbol{\\sigma}}\n\\newcommand{\\blambda}{\\boldsymbol{\\lambda}}\n\\newcommand{\\bphi}{\\boldsymbol{\\phi}}\n\\newcommand{\\bpsi}{\\boldsymbol{\\psi}}\n\n% ==Cross Referencing Different Docs\n\\usepackage{xr}\n%\\externaldocument{causalprob-app}\n\n\\begin{document} \n\n\\newcommand{\\tit}{The Bayesian Modeling of Epidemiological Systems: Combining Machine Learning and Prior Science}\n%\n%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%\n%\n\\spacingset{1.25}\n\n\\if0\\blind\n\n{\\title{\\bf\\tit\\thanks{Thank you to X, Y, and Z for helpful comments on previous versions of this paper.}}\n  \\author{Author A\\thanks{Assistant Professor, Department of\n      Government, University of Texas at Austin.\n158 W 21st, Austin, TX 78712.\n      Email:\n      \\href{mailto:connor.jerzak@austin.utexas.edu}{connor.jerzak@austin.utexas.edu} URL:\n      \\href{https://www.connorjerzak.com}{ConnorJerzak.com}}\n\\and\nAuthors\n\n  \\date{\n    \\today\n  }\n}\n\n\\fi\n\n\n\\if1\\blind\n\\title{\\bf \\tit}\n\\fi\n\n\\maketitle\n\n\\pdfbookmark[1]{Title Page}{Title Page}\n\n\\thispagestyle{empty}\n\\setcounter{page}{0}\n         \n\\begin{abstract}\n\\noindent Abstract here \n\\vspace{.25in}\n\\\\ \\noindent {\\bf Keywords:}  Epidemiological modeling; Machine learning; COVID-19; Bayesian methods  \\end{abstract}\n\n\n%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%\n\n\\clearpage\n\\spacingset{1.83}\n\\singlespacing \n\\tableofcontents\n\n\\section{Introduction} \nLet $\\gst(a)$ return the $q$ that solves \n\\begin{align*}\nX &\\sim \\textrm{Distribution}(q)\n\\\\\\textrm{s.t. } \\mathbb{E}[X] &= a.\n\\end{align*}\nWhy do we need something like this? Because $\\E[f(X)] \\ne \\E[X]$, and the way we impose constraints on the parameters (e.g., to be positive) act like $f(\\cdot)$'s.\n\\\\ \\vspace{0.1cm}\n\\\\ \\Verb|%%%START BAYES ODE%%%|\n%%%START BAYES ODE%%%\n\n%%%Priors \n\\begin{itemize}\n\\item $N \\leftarrow 10000$  % population scaling factor\n\\item $\\InvSoftPlus(\\beta_{l}) \\sim \\Dist{Normal}(\\gst(1/5),0.1)$\n\\item $\\InvSoftPlus(\\gamma) \\sim \\Dist{Normal}(\\gst(1/5),0.1)$\n\\item $\\InvSoftPlus(\\sigma) \\sim \\Dist{Normal}(\\gst(0.2),0.1)$\n\\item $\\InvSigmoid(\\delta) \\sim \\Dist{Normal}(\\gst(0.01),0.0001)$ % mortality rate (assumed to be the same as the birth rate)\n\\item $s_{l0} \\sim \\Dist{Normal}(0, 0.1)$ % initial sus frac (multiply by N to get number) \n\\item $e_{l0} \\sim \\Dist{Normal}(0, 0.1)$ % initial exposed frac (multiply by N to get total number) \n\\item $i_{l0}\\sim \\Dist{Normal}(0, 0.1)$ % initial infected frac (multiply by N to get total number) \n\\item $r_{l0} \\sim \\Dist{Normal}(0, 0.1)$  %initial recovered frac (multiply by N to get total number) \n\\item $\\Evolve{s_l} = -\\beta_{l} \\cdot i_l \\cdot s_l$\n\\item $\\Evolve{e_l} = \\beta_{l} \\cdot  i_l \\cdot  s_l - \\sigma \\cdot  e_l$\n\\item $\\Evolve{i_l} = \\sigma \\cdot e_l - \\gamma \\cdot  i_l$\n\\item $\\Evolve{r_l} = \\gamma \\cdot  i_l$\n\\item $\\Observe = \\Sigmoid( \\delta ) \\cdot i_l$ % deaths\n\\item $\\Observe = r_l$ % for compatibility with two outcomes case  \n\\end{itemize}\n\n%%%END BAYES ODE%%%\n\n\\Verb|%%%END BAYES ODE%%%|\n\n\\subsection{Additional Information} \n\\begin{itemize}\n\\item Surrogate posterior mean for parameters (e.g., $\\sigma$) and initial conditions (e.g., $i_o$) obtained via $f(\\mathbf{D})$, where $f$ is a parametric machine learning model  and $\\mathbf{D}$ is input data.\n\\begin{itemize}\n\\item Current $f(\\cdot)$ is a transformer + LSTM + dense neural network \n\\end{itemize}\n\\item For time-dependent parameters (e.g., $\\beta_t$): \n\\begin{itemize}\n\\item Cannot easily apply continuous time $\\beta_t$ since unclear how prior would be incorporated across continuous time domain \n\\item Instead: discrete resolution $\\beta_t$ \n\\begin{itemize}\n\\item Example: in a year, predict (1st, 2nd, 3rd, 4th quarter $\\beta$ values)\n\\item Interpolation used between $t$ slices \n\\end{itemize}\n\\end{itemize}\n\\end{itemize}\n\n\\begin{figure}[H]\n \\begin{center}\n   \\includegraphics[width=0.45\\linewidth]{Screenshot 2023-01-04 at\n     8.54.33 AM.png}\n   \\includegraphics[width=0.45\\linewidth]{Screenshot 2023-01-04 at ",
    "8.55.10 AM.png}\n\\end{center}\n\\caption{Predicted $\\beta_t$'s. }%\\label{fig}\n\\end{figure}\n\n\n\n{\\sc Prior Calibration}\n\\begin{itemize}\n\\item Priors are important \n\\item Reasonable priors over parameters may induce unreasonable prior predictive distribution \n\\begin{itemize}\n\\item Complex aggregation of parameters not easy to conceptualize via individual parameter priors \n\\item Adding joint correlations in prior usually not done due to a lack of information\n\\item One way to explore ``effects'' of prior on induced predictive distribution: \n\\begin{itemize}\n\\item Calculate $\\E_{\\textrm{Prior}}\\left[ \\sum_{i=1}^N \\log(p(Y_i))\\right]$;\n\\begin{itemize}\n\\item This is the expected likelihood of the data under the prior specification. \n\\item Hopefully, the priors are good and $\\E_{\\textrm{Prior}}[ p(Y_i)]$ is large \n\\end{itemize}\n\\item Calculate $\\nabla_{\\textrm{Prior Parameters}} \\E_{\\textrm{Prior}}\\left[ \\sum_{i=1}^N \\log(p(Y_i))\\right]$\n\\begin{itemize}\n\\item {\\it ``Derivative of the expected likelihood, with respect to the parameters specifying the priors'' }\n\\item This quantifies how sensitive the expected likelihood is to changes in a given prior parameter. \n\\item In the example from the real data, we see that the expected likelihood is most sensitive to choice of $\\sigma$ \n\\item If priors happened to be at their optimal values $\\leadsto$ small gradient values \n\\item Big gradient values indicate possibility of poor prior misspecification \n\\item Calculated via automatic differentiation with re-parameterized sampling (approach also used in variational inference estimation of approximate posterior)\n\\end{itemize}\n\\end{itemize}\n\\end{itemize}\n\\end{itemize}\n\n\\begin{figure}[H]\n \\begin{center}\n   \\includegraphics[width=0.95\\linewidth]{Screenshot 2023-01-04 at 8.44.37 AM.png}\n\\end{center}\n\\caption{Some of the model specifications. }%\\label{fig}\n\\end{figure}\n\n\\begin{figure}[H]\n \\begin{center}\n   \\includegraphics[width=0.95\\linewidth]{Screenshot 2023-01-04 at 8.42.51 AM.png}\n\\end{center}\n\\caption{Model results on the real data. Prior period +cumulative infections/hospitalizations/deaths, as well as stringency index used in ML model. $\\beta_t$ here has a resolution of 6 (6 distinct $\\beta_t$'s predicted, interpolations for in-between periods) }%\\label{fig}\n\\end{figure}\n\n\\begin{figure}[H]\n \\begin{center}\n   \\includegraphics[width=0.95\\linewidth]{Screenshot 2023-01-04 at 8.42.57 AM.png}\n\\end{center}\n\\caption{Model results on the real data. Prior period +cumulative infections/hospitalizations/deaths, as well as stringency index used in ML model. }%\\label{fig}\n\\end{figure}\n\n\\begin{figure}[H]\n \\begin{center}\n   \\includegraphics[width=0.95\\linewidth]{Screenshot 2023-01-04 at 8.43.05 AM.png}\n\\end{center}\n\\caption{Model results on the real data. Prior period +cumulative infections/hospitalizations/deaths, as well as stringency index used in ML model. }%\\label{fig}\n\\end{figure}\n\n\\begin{figure}[H]\n \\begin{center}\n   \\includegraphics[width=0.95\\linewidth]{Screenshot 2023-01-04 at 8.43.28 AM.png}\n\\end{center}\n\\caption{Model results on the real data. Prior period +cumulative infections/hospitalizations/deaths, as well as stringency index used in ML model. }%\\label{fig}\n\\end{figure}\n\n\\begin{figure}[H]\n \\begin{center}\n   \\includegraphics[width=0.95\\linewidth]{Screenshot 2023-01-04 at 8.43.46 AM.png}\n\\end{center}\n\\caption{Model results on the real data. Prior period +cumulative infections/hospitalizations/deaths, as well as stringency index used in ML model. }%\\label{fig}\n\\end{figure}\n\n\\begin{figure}[H]\n \\begin{center}\n   \\includegraphics[width=0.95\\linewidth]{Screenshot 2023-01-04 at 12.22.08 PM.png}\n\\end{center}\n\\caption{Gradient analysis for prior mean terms. }%\\label{fig}\n\\end{figure}\n\n\\begin{figure}[H]\n \\begin{center}\n   \\includegraphics[width=0.95\\linewidth]{Screenshot 2023-01-04 at 1.02.37 PM.png}\n\\end{center}\n\\caption{Gradient analysis for prior variance-covariance terms. }%\\label{fig}\n\\end{figure}\n\n\\end{document}\n\n%%% Local Variables:\n%%% mode: latex\n%%% TeX-master: t\n%%% End:\n\n\n\n\n"
  ),
  `ModelTrainers/SuperLModel_TrainDefine.R` = paste0(
    "# Content of SuperLModel_TrainDefine.R\n{\n  print(\"Sarting SuperLModel_TrainDefine.R\")\n  # sort( sapply(ls(), function(zr){ object.size(eval(parse(text = zr))) }) )\n  # if(!SimMode){ save(input_df_red_full, file = \"./tmp_input_df_red_full.Rdata\"); rm ( input_df_red_full ) }\n  saveCheckpointCounter <- outSampCounter <- 0;\n  nRestarts <- 1L; LR_schedule <- optax$warmup_cosine_decay_schedule(warmup_steps = \n                                                                      (nWarmup <- max(c(min(c(100L,\n                                                                                              nSGD_DefiningLRSeq)),\n                                                                                              0.1*nSGD_DefiningLRSeq))),\n                                                                     decay_steps = max(c(101L,nSGD_DefiningLRSeq-nWarmup)),\n                                                                     init_value = LEARNING_RATE_MAX/100, \n                                                                     peak_value = LEARNING_RATE_MAX, \n                                                                     end_value =  LEARNING_RATE_MAX/100)\n  if(nRestarts %in% c(2,3)){ stop(\"Case not implemented in TrainDefine.R\") } \n  if(nRestarts > 3){\n    LR_schedule <- c(replicate(nRestarts-2L,\n                               optax$cosine_onecycle_schedule(transition_steps = jnp$array(ai(ceiling(nSGD_DefiningLRSeq/(nRestarts) ))),\n                                                              peak_value = jnp$array(LEARNING_RATE_MAX) )\n                              ), optax$cosine_decay_schedule( init_value = LEARNING_RATE_MAX, \n                                          decay_steps = ai(ceiling(nSGD_DefiningLRSeq/(nRestarts-3) ) )))\n    LR_schedule <- optax$join_schedules(LR_schedule,\n                                        boundaries = jnp$array(ai(ceiling(nSGD_DefiningLRSeq / nRestarts * 1:(nRestarts-1) ))))\n  }\n  nSGD_MASTER <- nSGD_DefiningLRSeq\n  #LR_schedule_vec <- np$array(  LR_schedule(jnp$array(1L:as.integer(nSGD_DefiningLRSeq) ) ))\n  LR_schedule_vec <- sapply(1:nSGD_MASTER, function(x_){ np$array(  LR_schedule(jnp$array(x_) ))})\n  plot( LR_schedule_vec )\n\n  if(T == T){ \n  optax_optimizer <-  optax$chain(\n    #optax$clip(1),\n    optax$adaptive_grad_clip( 0.1, eps = 0.0001 ),\n    optax$adabelief( learning_rate = LR_schedule, eps = 1e-6, eps_root = 1e-6 ) \n    #optax$adamw( learning_rate = LR_schedule  ) \n  )\n  }\n  if(T == F){ \n    optax_shampoo <- import(\"optax_shampoo\")\n    optax_optimizer = optax_shampoo$distributed_shampoo$distributed_shampoo(\n      learning_rate=LR_schedule,\n      block_size=128L,\n      #beta1=0.9,\n      #beta2=0.999,\n      #diagonal_epsilon=1e-10,\n      #matrix_epsilon=1e-6,\n      #weight_decay=0.0,\n      #start_preconditioning_step=1000,\n      #preconditioning_compute_steps=1,\n      #statistics_compute_steps=1,\n      #best_effort_shape_interpretation=TRUE,\n      #graft_type=distributed_shampoo.GraftingType.ADAGRAD,\n      nesterov=TRUE,\n      exponent_override=0\n    )\n  }\n\n  # optimizer setup\n  opt_state <- optax_optimizer$init(  eq$partition(ModelList, eq$is_array)[[1]]  )\n  if (exists(\"ndm_runtime_replicate_tree\", inherits = TRUE)) {\n    opt_state <- ndm_runtime_replicate_tree(opt_state)\n  }\n  TrackBlockUpdateNorms <- isTRUE(get0(\"TrackBlockUpdateNorms\", inherits = TRUE, ifnotfound = FALSE))\n  PersistBlockUpdateNorms <- isTRUE(get0(\"PersistBlockUpdateNorms\", inherits = TRUE, ifnotfound = FALSE))\n  BlockUpdateTrackNames <- intersect(\n    c(\"InitProcessList\", \"LocalNeural\", \"GlobalNeural\", \"ScaleList\", \"TSList\", \"BNList\"),\n    names(ModelList)\n  )\n  train_define_env <- environment()\n  block_metric_norm <- function(tree) {\n    leaves <- jax$tree_util$tree_leaves(tree)\n    if (length(leaves) == 0L) {\n      return(jnp$array(0.))\n    }\n    optax$global_norm(leaves)\n  }\n  block_update_log <- data.frame(\n    iter = integer(0L),\n    block = character(0L),\n    param_norm = numeric(0L),\n    grad_norm = numeric(0L),\n    update_norm = numeric(0L),\n    rel_update = numeric(0L),\n    stringsAsFactors = FALSE\n  )\n  append_block_update_log <- function(iteration, block_metrics) {\n    if (!TrackBlockUpdateNorms || is.null(block_metrics) || length(block_metrics) == 0L) {\n      return(invisible(NULL))\n    }\n    py_scalar_num <- function(x) {\n      value <- suppressWarnings(as.numeric(np$array(x)))\n      if (length(value) == 0L) {\n        return(NA_real_)\n      }\n      value[[1L]]\n    }\n    rows <- do.call(\n      rbind,\n      lapply(names(block_metrics), function(block_name) {\n        metric <- block_metrics[[block_name]]\n        data.frame(\n          iter = as.integer(iteration),\n          block = block_name,\n          param_norm = py_scalar_num(metric$param_norm),\n          grad_norm = py_scalar_num(metric$grad_norm),\n          update_norm = py_scalar_num(metric$update_norm),\n          rel_update = py_scalar_num(metric$rel_update),\n          stringsAsFactors = FALSE\n        )\n      })\n    )\n    current_log <- get(\"block_update_log\", envir = train_define_env, inherits = FALSE)\n    updated_log <- rbind(current_log, rows)\n    assign(\"block_update_log\", updated_log, envir = train_define_env)\n    if (PersistBlockUpdateNorms) {\n      data.table::fwrite(\n        updated_log,\n        file.path(HolderFolder, sprintf(\"block_updates_i%s.csv\", as.integer(iteration)))\n      )\n    }\n    invisible(rows)\n  }\n  jit_apply_updates <- eq$filter_jit(optax$apply_updates)\n  jit_get_update <- eq$filter_jit(optax_optimizer$update)\n  train_step_compiled <- switch_filter_jit(function(ModelList,\n                                                    batch_pkg,\n                                                    y_true,\n                                                    y_mask,\n                                                    iteration,\n  ",
    "                                                  state,\n                                                    PriorList,\n                                                    PolicyList,\n                                                    GetPredSaveAtInfo,\n                                                    seed,\n                                                    opt_state) {\n    loss_and_grads <- eq$filter_value_and_grad(getLoss_train, has_aux = T)(\n      ModelList,\n      batch_pkg,\n      y_true,\n      y_mask,\n      iteration,\n      state,\n      PriorList,\n      PolicyList,\n      GetPredSaveAtInfo,\n      seed\n    )\n    loss_and_state <- loss_and_grads[[1]]\n    grads <- loss_and_grads[[2]]\n    model_arrays <- eq$partition(ModelList, eq$is_array)\n    model_array_tree <- model_arrays[[1]]\n    grad_arrays <- eq$partition(grads, eq$is_inexact_array)[[1]]\n    updates_and_state <- optax_optimizer$update(\n      grad_arrays,\n      opt_state,\n      model_array_tree\n    )\n    block_update_metrics <- if (TrackBlockUpdateNorms && length(BlockUpdateTrackNames) > 0L) {\n      metrics <- lapply(BlockUpdateTrackNames, function(block_name) {\n        param_norm <- block_metric_norm(model_array_tree[[block_name]])\n        grad_norm <- block_metric_norm(grad_arrays[[block_name]])\n        update_norm <- block_metric_norm(updates_and_state[[1]][[block_name]])\n        rel_update <- update_norm / jnp$maximum(\n          param_norm,\n          jnp$array(1e-12)$astype(param_norm$dtype)\n        )\n        list(\n          \"param_norm\" = param_norm,\n          \"grad_norm\" = grad_norm,\n          \"update_norm\" = update_norm,\n          \"rel_update\" = rel_update\n        )\n      })\n      names(metrics) <- BlockUpdateTrackNames\n      metrics\n    } else {\n      NULL\n    }\n    updated_model <- eq$combine(\n      optax$apply_updates(model_array_tree, updates_and_state[[1]]),\n      model_arrays[[2]]\n    )\n    list(\n      \"loss\" = loss_and_state[[1]],\n      \"state\" = loss_and_state[[2]],\n      \"grad_norm\" = optax$global_norm(jax$tree_util$tree_leaves(grad_arrays)),\n      \"model\" = updated_model,\n      \"opt_state\" = updates_and_state[[2]],\n      \"block_update_metrics\" = block_update_metrics\n    )\n  })\n}\n\n# perform main training sequence\nNA20 <- function(zer){zer[is.na(zer)] <- 0;zer[is.infinite(zer)] <- 0;zer}\ngrad_norm_vec <- out_loss_vec <- in_loss_vec <- rep(NA, times = nSGD_DefiningLRSeq );i_<-1\ngrad_norm_mat <- c()\nLastOutCor <- Skill8SanityCheck <- NA\nte_total <- te_grads <- 0\nst0 <- Sys.time()\nplottingSeq_counter <- ExecuteUpdateCounter <- 0; GradNorm_jit <- jax$jit(optax$global_norm)\ncrossIterCor_vec <- c()\n\n# create save directory for results\nSavedModelDir <- sprintf(\"./SavedModels/%s/Model_%s_%s\",\n                         ifelse(grepl(tolower(AnalysisName), pattern = \"sim\"),\n                                yes = \"FromSim\",no=\"FromReal\"),\n                         AnalysisName,\n                         AnalysisDate)\nif(dir.exists(SavedModelDir)){\n  SavedModelDir <- sprintf(\"%s_%s\", SavedModelDir, format(Sys.time(), \"%H-%M-%S\"))\n}\ndir.create(SavedModelDir, recursive = TRUE, showWarnings = FALSE)\n\n# calculate total parameter number\nprint2(sprintf(\"Total trainable parameter count: %s\",\n               nParams <- sum(unlist(lapply(jax$tree$leaves( eq$partition(ModelList, eq$is_array)[[1]] ), function(zer){zer$size})))))\nprint(\"Done with SuperLModel_TrainDefine.R\")"
  ),
  `ModelTrainers/SuperLModel_TrainDo.R` = paste0(
    "# Content of SuperLModel_TrainDo.R\nprint(\"Sarting SuperLModel_TrainDo.R\")\nSavedModelDir <- get0(\n  \"SavedModelDir\",\n  ifnotfound = sprintf(\"./SavedModels/%s/Model_%s_%s\",\n                       ifelse(grepl(tolower(AnalysisName), pattern = \"sim\"),\n                              yes = \"FromSim\", no = \"FromReal\"),\n                       AnalysisName,\n                       AnalysisDate)\n)\ncheckpoint_file <- function(prefix, step){\n  file.path(SavedModelDir, sprintf(\"%s_i%s_%s_%s.eqx\", prefix, step, AnalysisName, AnalysisDate))\n}\nreset_train_iterator <- function(){\n  TFDatasetIterator_train <<- reticulate::as_iterator(TFDataset_train)\n  TFDatasetIterator_train\n}\nbatch_has_expected_shape <- function(dat_, expected_batch_size){\n  if(\"try-error\" %in% class(dat_) || is.null(dat_) || length(dat_) == 0L){\n    return(FALSE)\n  }\n  batch_dims <- try(vapply(dat_, function(l_){ as.integer(np$array(l_$shape)[[1]]) }, integer(1)), TRUE)\n  if(\"try-error\" %in% class(batch_dims) || length(batch_dims) == 0L || any(is.na(batch_dims))){\n    return(FALSE)\n  }\n  batch_size <- batch_dims[[1]]\n  batch_size > 0L && batch_size == expected_batch_size && all(batch_dims == batch_size)\n}\nnext_train_batch <- function(max_attempts = 100L){\n  for(attempt_i in seq_len(max_attempts)){\n    dat_ <- try(reticulate::iter_next(TFDatasetIterator_train), TRUE)\n    if(batch_has_expected_shape(dat_, nBatch)){\n      return(TFConst2JAXArray(dat_))\n    }\n    print2(sprintf(\"Resetting train iterator in TrainDo.R [attempt %s]\", attempt_i))\n    reset_train_iterator()\n  }\n  stop(\"Too many malformed batches in TrainDo.R\")\n}\nsave_eqx_enabled <- isTRUE(get0(\"SaveEqx\", ifnotfound = TRUE))\nrecover_checkpoint_at <- get0(\"RecoverCheckpointAt\", ifnotfound = NULL)\nif(isTRUE(recover_checkpoint_at)){\n  recover_checkpoint_at <- \"last\"\n}\ncheckpoint_has_scale_state <- function(){\n  exists(\"SIM_GLOBAL_SCALE_MEAN\", inherits = TRUE) &&\n    exists(\"SIM_GLOBAL_SCALE_SD\", inherits = TRUE)\n}\ncheckpoint_scale_state <- function(){\n  if(!checkpoint_has_scale_state()){\n    return(NULL)\n  }\n  jnp$array(list(SIM_GLOBAL_SCALE_MEAN, SIM_GLOBAL_SCALE_SD))\n}\ncheckpoint_model_payload <- function(){\n  payload <- list(ModelList, state, opt_state)\n  scale_state <- checkpoint_scale_state()\n  if(!is.null(scale_state)){\n    payload[[4]] <- scale_state\n  }\n  payload\n}\nrestore_checkpoint_scale_state <- function(recovered_payload){\n  if(length(recovered_payload) < 4L || is.null(recovered_payload[[4]])){\n    return(invisible(NULL))\n  }\n  SIM_GLOBAL_SCALE_MEAN <<- jnp$take(recovered_payload[[4]], 0L, axis = 0L)$tolist()\n  SIM_GLOBAL_SCALE_SD <<- jnp$take(recovered_payload[[4]], 1L, axis = 0L)$tolist()\n  invisible(NULL)\n}\nndm_condition_message <- utils::getFromNamespace(\".ndm_condition_message\", \"ndm\")\nndm_numeric_summary <- utils::getFromNamespace(\".ndm_numeric_summary\", \"ndm\")\nndm_first_nonfinite_name <- utils::getFromNamespace(\".ndm_first_nonfinite_name\", \"ndm\")\nndm_write_nonfinite_report <- utils::getFromNamespace(\".ndm_write_nonfinite_report\", \"ndm\")\nnonfinite_empty_summary <- function(error = NA_character_){\n  list(\n    error = error,\n    dims = integer(),\n    length = 0L,\n    finite_fraction = NA_real_,\n    n_nonfinite = NA_integer_,\n    n_nan = NA_integer_,\n    n_inf = NA_integer_,\n    min = NA_real_,\n    max = NA_real_,\n    mean = NA_real_,\n    first_nonfinite_index = integer()\n  )\n}\nnonfinite_capture_summary <- function(expr){\n  value <- try(eval.parent(substitute(expr)), silent = TRUE)\n  if(inherits(value, \"try-error\")){\n    return(nonfinite_empty_summary(ndm_condition_message(value)))\n  }\n  ndm_numeric_summary(value, np = np)\n}\ncapture_nonfinite_learning_rate <- function(iteration){\n  if(!exists(\"LR_schedule_vec\", inherits = TRUE) || length(LR_schedule_vec) < iteration){\n    return(NA_real_)\n  }\n  suppressWarnings(as.numeric(LR_schedule_vec[[iteration]])[[1L]])\n}\ncapture_nonfinite_base_id <- function(){\n  if(!exists(\"SimEntry\", inherits = TRUE) || is.null(SimEntry) || is.null(SimEntry$BaseID)){\n    return(NA_integer_)\n  }\n  suppressWarnings(as.integer(as.numeric(SimEntry$BaseID)[[1L]]))\n}\ncapture_nonfinite_report <- function(batch_l,\n                                     loss_value,\n                                     grad_norm_value,\n                                     iteration,\n                                     keys_mat){\n  GetPredSaveAtInfo_runtime <- if (exists(\"ndm_runtime_normalize_getpred_saveat_info\", inherits = TRUE)) {\n    ndm_runtime_normalize_getpred_saveat_info(GetPredSaveAtInfo_default)\n  } else {\n    GetPredSaveAtInfo_default\n  }\n  prediction <- try(\n    GetPred_train_jit(\n      ModelList,\n      batch2package(batch_l),\n      state,\n      PriorList,\n      PolicyList,\n      GetPredSaveAtInfo_runtime,\n      keys_mat\n    ),\n    silent = TRUE\n  )\n\n  tensor_summaries <- list(\n    batch_YTrue_out = nonfinite_capture_summary(batch_l$YTrue_out),\n    batch_YTrue_out_mask = nonfinite_capture_summary(batch_l$YTrue_out_mask),\n    batch_YTrue = nonfinite_capture_summary(batch_l$YTrue),\n    batch_YTrue_mask = nonfinite_capture_summary(batch_l$YTrue_mask),\n    batch_XPred = nonfinite_capture_summary(batch_l$XPred),\n    batch_XPred_mask = nonfinite_capture_summary(batch_l$XPred_mask)\n  )\n\n  if(inherits(prediction, \"try-error\")){\n    tensor_summaries$prediction_forward_pass <- nonfinite_empty_summary(ndm_condition_message(prediction))\n  } else {\n    pred_obj <- prediction[[1]]\n    tensor_summaries$prediction_y_mu <- nonfinite_capture_summary(pred_obj$y_mu)\n    tensor_summaries$prediction_y_sigma <- nonfinite_capture_summary(pred_obj$y_sigma)\n    tensor_summaries$prediction_center_param <- nonfinite_capture_summary(pred_obj$ODEParamsSampList$center_param)\n    tensor_summaries$prediction_scale_param <- nonfinite_capture_summary(pred_obj$ODEParamsSampList$scale_param)\n  ",
    "  tensor_summaries$prediction_s_l <- nonfinite_capture_summary(pred_obj$ODEParamsSampList$s_l_samp)\n    tensor_summaries$prediction_e_l <- nonfinite_capture_summary(pred_obj$ODEParamsSampList$e_l_samp)\n    tensor_summaries$prediction_i_l <- nonfinite_capture_summary(pred_obj$ODEParamsSampList$i_l_samp)\n    tensor_summaries$prediction_r_l <- nonfinite_capture_summary(pred_obj$ODEParamsSampList$r_l_samp)\n    tensor_summaries$prediction_raw_beta_t <- nonfinite_capture_summary(pred_obj$ODEParamsSampList$diff_eq_sol_ys$raw_beta_t)\n    tensor_summaries$prediction_raw_policy_t <- nonfinite_capture_summary(pred_obj$ODEParamsSampList$diff_eq_sol_ys$raw_policy_t)\n    tensor_summaries$prediction_neural1 <- nonfinite_capture_summary(pred_obj$ODEParamsSampList$diff_eq_sol_ys$Neural1)\n  }\n\n  outer_iteration <- get0(\"OUTER_ITERATION\", ifnotfound = NA_integer_)\n  report <- list(\n    analysis_name = get0(\"AnalysisName\", ifnotfound = NA_character_),\n    outer_iteration = outer_iteration,\n    iteration = as.integer(iteration),\n    base_id = capture_nonfinite_base_id(),\n    model_type = get0(\"ModelType\", ifnotfound = NA_character_),\n    n_samples_train = suppressWarnings(as.integer(get0(\"nSamplesTrain\", ifnotfound = NA_integer_))),\n    model_depth = suppressWarnings(as.integer(get0(\"ModelDepth\", ifnotfound = NA_integer_))),\n    model_dims = suppressWarnings(as.integer(get0(\"ModelDims\", ifnotfound = NA_integer_))),\n    context_length = suppressWarnings(as.integer(get0(\"nTimesPast\", ifnotfound = NA_integer_))),\n    learning_rate = capture_nonfinite_learning_rate(iteration),\n    loss = loss_value,\n    grad_norm = grad_norm_value,\n    sim_entry = if(exists(\"SimEntry\", inherits = TRUE)) SimEntry else NULL,\n    tensor_summaries = tensor_summaries,\n    first_bad_tensor = ndm_first_nonfinite_name(tensor_summaries)\n  )\n  report_path <- ndm_write_nonfinite_report(\n    report = report,\n    holder_folder = HolderFolder,\n    outer_iteration = outer_iteration,\n    iteration = iteration\n  )\n  list(report = report, report_path = report_path)\n}\nif (exists(\"ndm_runtime_normalize_getpred_saveat_info\", inherits = TRUE)) {\n  GetPredSaveAtInfo_default <- ndm_runtime_normalize_getpred_saveat_info(GetPredSaveAtInfo_default)\n}\nfor(i in i_:nSGD_model){\n  if(Sys.info()[\"sysname\"] != \"Darwin\" & i > 2){  \n    #write.csv( file=\"./i_.csv\",data.frame(\"i\" = i, \"te_total\" = as.numeric(te_total, units = \"secs\"), \"te_grad\" = as.numeric(te_grads, units = \"secs\") ))  \n  }\n  # save model checkpoints\n  if(nCheckpoints > 0){\n  CheckPointSaveAt <- unique(c(round(10^(seq(log(10,base=10), \n                                             log(nSGD_MASTER,base=10), \n                                             length.out = nCheckpoints)),0L),\n                               nSGD_MASTER))\n  if(  i %in% CheckPointSaveAt ){\n    print2( \"Saving checkpoint (Optimizer, Model, Model-generating Code)...\" )\n    saveCheckpointCounter <- saveCheckpointCounter + 1\n\n    if(saveCheckpointCounter == 1){\n      zip::zip(zipfile = file.path(SavedModelDir, sprintf(\"AnalysisR_%s_%s.zip\", AnalysisName, AnalysisDate)),\n               files = NDM_INTERNAL_ANALYSIS_DIR)\n    }\n\n    if(i %in% CheckPointSaveAt){ save_i <- i }\n    if(save_eqx_enabled){ \n      # save_i <- \"last\"\n      eq$tree_serialise_leaves(checkpoint_file(\"ModelList\", save_i),\n                               checkpoint_model_payload())\n      if(\"ModelList_notshared_set\" %in% ls()){\n        eq$tree_serialise_leaves(checkpoint_file(\"ModelList_notshared_set\", save_i),\n                                 list(ModelList_notshared_set, # nonshared parameters \n                                      lapply(sim_dat_norm_list,jnp$array)) # means for recovery \n                                 ) \n      }\n    }\n\n    # recover trained model\n    if(save_eqx_enabled && !is.null(recover_checkpoint_at)){\n      # nSGD_model / 1:4 # defines i's\n      RecoverAt <- recover_checkpoint_at\n      ModelList_recovered <- eq$tree_deserialise_leaves(\n        checkpoint_file(\"ModelList\", RecoverAt),\n        checkpoint_model_payload()) \n      if(\"ModelList_notshared_set\" %in% ls()){\n        ModelList_notshared_set_recovered <- eq$tree_deserialise_leaves(checkpoint_file(\"ModelList_notshared_set\", RecoverAt),\n                                 list(ModelList_notshared_set, # non shared parameters \n                                      lapply(sim_dat_norm_list,jnp$array) ) # norm factors \n                                 )\n        sim_dat_norm_list <- ModelList_notshared_set_recovered[[2]] \n        sim_dat_norm_list <- lapply(sim_dat_norm_list,function(l_){\n          SIM_GLOBAL_SCALE_MEAN_ <- jnp$take(l_,0L,axis=0L)$tolist()\n          SIM_GLOBAL_SCALE_SD_ <- jnp$take(l_,1L,axis=0L)$tolist()\n          list(SIM_GLOBAL_SCALE_MEAN_, SIM_GLOBAL_SCALE_SD_)\n        })\n        restore_checkpoint_scale_state(ModelList_recovered)\n        ModelList_notshared_set <- ModelList_notshared_set_recovered[[1]]\n      }\n\n      # confirm \n      restore_checkpoint_scale_state(ModelList_recovered)\n      # opt_state[[1]]\n      # opt_state[[3]][[1]]\n      opt_state <- ModelList_recovered[[3]];\n      state <- ModelList_recovered[[2]];\n      ModelList <- ModelList_recovered[[1]]\n      if (exists(\"ndm_runtime_replicate_tree\", inherits = TRUE)) {\n        opt_state <- ndm_runtime_replicate_tree(opt_state)\n        state <- ndm_runtime_replicate_tree(state)\n        ModelList <- ndm_runtime_replicate_tree(ModelList)\n      }\n      i_ <- np$array( opt_state[[4]][[2]]$count )\n      rm( ModelList_recovered )\n    }\n  }\n\n  # save analytics\n  if( i %in% CheckPointSaveAt  ){\n    print2( sprintf(\"Starting GetAnalytics.R at %s of %s\", i, nSGD_model) )\n    outSampCounter <- outSampCounter+1;ndm_source_extracted(\"ResultsGet/SuperLModel_GetAnalytics.R\")\n  }\n  }\n  \n  i_ <- i; fulliter_timer <- Sys.time()\n  if(i %% 10 == 0){  print(",
    "i); gc(); py_gc$collect() }\n\n  # get batch\n  if(nSGD_pretrain > 0L | nSGD_posttrain > 0){ \n  dat_ <- next_train_batch()\n\n  # update step\n  {\n    gd_timer <- Sys.time()\n    if( i == 1 ){ print2( \"At first gradLoss_jax()\" ) }\n    keys_mat <- ndm_runtime_data_to_device(jax$random$split(JaxKey(ai(i)),nBatch))\n    batch_pkg <- batch2package(dat_)\n    GetPredSaveAtInfo_runtime <- if (exists(\"ndm_runtime_normalize_getpred_saveat_info\", inherits = TRUE)) {\n      ndm_runtime_normalize_getpred_saveat_info(GetPredSaveAtInfo_default)\n    } else {\n      GetPredSaveAtInfo_default\n    }\n    train_step_result <- train_step_compiled(\n      ModelList,\n      batch_pkg,\n      dat_$YTrue_out,\n      dat_$YTrue_out_mask,\n      jnp$array(as.numeric(i)),\n      state,\n      PriorList,\n      PolicyList,\n      GetPredSaveAtInfo_runtime,\n      keys_mat,\n      opt_state\n    )\n    Loss_i <- in_loss_vec[i] <- suppressWarnings(as.numeric(np$array(train_step_result$loss))[[1L]])\n    GradNorm_i <- grad_norm_vec[i] <- suppressWarnings(as.numeric(np$array(train_step_result$grad_norm))[[1L]])\n\n    UpdateParametersCond <- is.finite(Loss_i) & is.finite(GradNorm_i)\n    if(! UpdateParametersCond ){\n      nonfinite_capture <- capture_nonfinite_report(\n        batch_l = dat_,\n        loss_value = Loss_i,\n        grad_norm_value = GradNorm_i,\n        iteration = i,\n        keys_mat = keys_mat\n      )\n      stop(\n        sprintf(\n          paste(\n            \"Non-finite training state in %s\",\n            \"[outer=%s, BaseID=%s, ModelType=%s, iter=%s, loss=%s, grad_norm=%s].\",\n            \"Saved debug report to %s.\",\n            sep = \" \"\n          ),\n          get0(\"AnalysisName\", ifnotfound = \"Analysis2\"),\n          get0(\"OUTER_ITERATION\", ifnotfound = NA_integer_),\n          capture_nonfinite_base_id(),\n          get0(\"ModelType\", ifnotfound = NA_character_),\n          i,\n          format(Loss_i, scientific = TRUE),\n          format(GradNorm_i, scientific = TRUE),\n          nonfinite_capture$report_path\n        )\n      )\n    }\n    if( UpdateParametersCond){\n      ExecuteUpdateCounter <- ExecuteUpdateCounter + 1\n      if (exists(\"append_block_update_log\", inherits = TRUE)) {\n        append_block_update_log(i, train_step_result$block_update_metrics)\n      }\n      ModelList <- train_step_result$model\n      state <- train_step_result$state\n      opt_state <- train_step_result$opt_state\n      rm(batch_pkg, dat_)\n    }\n\n      # plotting sequence (do this after all parameter + state updates complete)\n      {\n      if( (i == 1 | i %% 10 == 0)  & is.na(COMMAND_ARG_INPUT) ){\n          plottingSeq_counter <- plottingSeq_counter + 1\n          if(plottingSeq_counter == 1){ print2( \"First plotting seq analysis\"  ) }\n          par(mfrow = c(1,2))\n          for(reri in 1:2){\n            # tmp2 <- GetPred_train_jit( ModelList, jax_batchx, state, PriorList, PolicyList, jax$random$split(JaxKey(ai(runif(1,1,100000))), nBatch))\n            # plot( np$array( tmp2[[1]]$y_mu )[,,1] ) ; plot( c(np$array( tmp2[[1]]$y_sigma[,,1] ) ))\n            ( {tmp555 <- np$array(GetPred_train_jit(\n              ModelList, batch2package(batch_l_cal),\n              state, PriorList, PolicyList,\n              GetPredSaveAtInfo_runtime,\n              ndm_runtime_data_to_device(jax$random$split(JaxKey(ai(runif(1,1,100000))), nBatch)))[[1]]$y_mu)[,,1] })\n            if(reri == 1){ tmp_ <- tmp555 }\n            if(reri == 1){ try(plot(tmp555[1,],ylim = c(0,max(tmp555)),type = 'l',main=\"Y-hat\"),T) }\n            for(i3 in 2:nrow(tmp555)){ points(tmp555[i3,],type = 'l',col = ifelse(reri == 1, yes = \"black\", no = \"gray\"),\n                                           lwd = ifelse(reri == 1, yes = 2, no = 2),\n                                           lty = ifelse(reri == 1, yes = 1, no = 2)) }\n          }\n\n          # plot compare against truth\n          tmp_true <- np$array(batch_l_cal$YTrue_out)[,,1]\n          try(plot(tmp_true[1,],ylim = c(0,max(tmp_true)),type = 'l',main=\"Y-true\"),T)\n          for(i3 in 2:nrow(tmp555)){ points(tmp_true[i3,],type = 'l',col = \"black\",\n                                         lwd = 2,\n                                         lty = 1) }\n          print(sprintf(\"Current cor with truth: %.3f\", cor(c(tmp555),c(tmp_true))))\n          \n          plot(c(tmp555),c(tmp_true),\n               xlim = summary(c(tmp555,tmp_true))[c(1,6)],\n               ylim = summary(c(tmp555,tmp_true))[c(1,6)]); abline(a=0,b=1); \n          plot(c(tmp555),c(tmp_true),\n               xlim = summary(c(tmp555,tmp_true))[c(1,6)],\n               ylim = summary(c(tmp555,tmp_true))[c(1,6)]);abline(a=0,b=1)\n\n          print2(sprintf(\"Within iteration mean correlation: %.10f\", mean( diag( cor(t(tmp_), t(tmp555))) ) ))\n          if(plottingSeq_counter == 1){ sharedXSamp <- sample(1:length(tmp555),length(tmp555)/10) }\n          if(plottingSeq_counter > 1){\n            crossIterCor_vec <- c(crossIterCor_vec, cor(tmp555[sharedXSamp], tmpSamp_minus1))\n            print2( sprintf(\"Across iteration correlation: %.10f\",crossIterCor_vec[ length(crossIterCor_vec) ]) )\n          }\n          if(i == 1){ tmpSamp_t0 <- tmp555[sharedXSamp] }\n          tmpSamp_minus1 <- tmp555[sharedXSamp] # update minus 1 value\n          #rm(tmp555,tmp_,tmp_true)\n          rm(tmp_,tmp_true)\n      }\n      if( (i > 10 & i %% 10 == 5) & is.na(COMMAND_ARG_INPUT) ){\n        par(mfrow=c(1,2)); try({plot(rank(na.omit(in_loss_vec)),main=\"Loss\"); points(smooth.spline(rank(na.omit(in_loss_vec))),type = \"l\",lwd=3)},T)\n        try({plot(grad_norm_vec[1:i],log = 'y',main=\"Gradients\")},T)\n      }\n      }\n\n      # print results\n      if (i == 1 || (is.na(COMMAND_ARG_INPUT) && i %% 4 == 0L) ||\n            (!is.na(COMMAND_ARG_INPUT) && i %% 20 == 0L)) {\n          print2( sprintf(\"Iter: %s of %s -- Loss: %.4f (%.3f%%) -- Last OutCor %.2f: -- Last OutSkill: %.2f -- T",
    "otal (s): %s -- Grad & updates (s): %.3f\",\n                            i, nSGD_model, \n                            Loss_i,\n                            100*(1-rank(in_loss_vec[1:i])[i]/i),\n                            LastOutCor, Skill8SanityCheck,\n                            te_total <- round(difftime(Sys.time(), fulliter_timer, units = \"secs\"),2L), \n                            te_grads <- round(difftime(Sys.time(), gd_timer, units = \"secs\"),2L) )   )\n      }\n      write.csv(file = './TrainDoStepTime.csv', as.matrix(te_total))\n    }\n  }\n}\nprint(\"Done with SuperLModel_TrainDo.R\")"
  ),
  `ResultsAnalyze/SuperLModel_GenFigs_GenInputStats.R` = "# Content of SuperLModel_GenFigs_InputStats.R\n{\n  ##############################################################################\n  # Purpose: Generate concise TeX macros (\\newcommand{}) containing key summary\n  #          statistics for referencing in LaTeX.  Place at the end of \n  #          SuperLModel_GenFigs.R (after res_mat has been created).\n  ##############################################################################\n\n  simModeStr <- if (SimMode) \"True\" else \"False\"\n  \n  table(res_mat$i_in_sgd)\n  tapply(res_mat$RSSBaselineSummary, res_mat$nSamplesTrain, mean)\n  # tapply(res_mat$RSSBaselineSummary, res_mat$c_endogeneous, median)\n  # tapply(res_mat$RSSBaselineSummary, res_mat$policy_effectiveness, median)\n  tapply(res_mat$RSSBaselineSummary, res_mat$nSamplesTrain, se)\n  \n  # Compute summary statistics for referencing in LaTeX (examples)\n  NObservations    <- nrow(res_mat)\n  NModelTypes      <- length(unique(res_mat$ModelType))\n  NUniqueDiseases  <- length(unique(res_mat$BaseID))\n  NTrainedModels  <- length(unique(res_mat$sim_index))\n  MaxSamplesTrain  <- max(res_mat$nSamplesTrain, na.rm=TRUE)\n  MedianFinalSkill  <- median(res_mat$SkillSummary[res_mat$i_in_sgd == max(res_mat$i_in_sgd)], na.rm=TRUE)\n  MedianFinalSkill_Decoder  <- median(res_mat$SkillSummary[res_mat$i_in_sgd == max(res_mat$i_in_sgd) & \n                                res_mat$ModelType==\"DecoderOnly\"], na.rm=TRUE)\n  MedianFinalSkill_NeuralODE  <- median(res_mat$SkillSummary[res_mat$i_in_sgd == max(res_mat$i_in_sgd) & \n                                  res_mat$ModelType==\"NeuralODE\"], na.rm=TRUE)\n  MaxFinalSkill   <- max(res_mat$SkillSummary[res_mat$i_in_sgd == max(res_mat$i_in_sgd)],\n                               na.rm=TRUE)\n  MinContextLength <- min(res_mat$ContextLength, na.rm=TRUE)\n  MaxContextLength <- max(res_mat$ContextLength, na.rm=TRUE)\n  \n  # generate outputs \n  output_lines <- c(\n    sprintf(\"\\\\newcommand{\\\\NObservationsSimMode%s}{%s}\",\n            simModeStr, format(NObservations, big.mark=\",\")),\n    \n    sprintf(\"\\\\newcommand{\\\\NModelTypesSimMode%s}{%i}\",\n            simModeStr, NModelTypes),\n    \n    sprintf(\"\\\\newcommand{\\\\MaxSamplesTrainSimMode%s}{%s}\",\n            simModeStr, format(as.integer(MaxSamplesTrain),big.mark=\",\")),\n    \n    sprintf(\"\\\\newcommand{\\\\MedianFinalSkillSimMode%s}{%.2f}\",\n            simModeStr, MedianFinalSkill),\n    \n    sprintf(\"\\\\newcommand{\\\\MedianFinalSkillDecoderOnlySimMode%s}{%.2f}\",\n            simModeStr, MedianFinalSkill_Decoder),\n    \n    sprintf(\"\\\\newcommand{\\\\MedianFinalSkillNeuralODESimMode%s}{%.2f}\",\n            simModeStr, MedianFinalSkill_NeuralODE),\n    \n    sprintf(\"\\\\newcommand{\\\\MaxFinalSkillSimMode%s}{%.2f}\",\n            simModeStr, MaxFinalSkill),\n    \n    sprintf(\"\\\\newcommand{\\\\MinContextLengthSimMode%s}{%i}\",\n            simModeStr, MinContextLength),\n    \n    sprintf(\"\\\\newcommand{\\\\NUniqueDiseasesSimMode%s}{%i}\",\n            simModeStr, NUniqueDiseases),\n    \n    sprintf(\"\\\\newcommand{\\\\NTrainedModelsSimMode%s}{%i}\",\n            simModeStr, NTrainedModels),\n    \n    sprintf(\"\\\\newcommand{\\\\MaxContextLengthSimMode%s}{%i}\",\n            simModeStr, MaxContextLength),\n    \n    alpha_macros\n  )\n  \n  # Write these stats to an output .tex file (which you can then \\input in LaTeX)\n  writeLines(output_lines, \n             con = sprintf(\"./Figures/InputStatisticsSimMode%s.tex\", simModeStr))\n  \n  message(\"Finished writing Figures/InputStatistics.tex with key stats.\")\n}\n",
  `ResultsAnalyze/SuperLModel_GenFigs_RealPreprocess.R` = paste0(
    "# Content of SuperLModel_GenFigs_RealPreprocess.R\n{\n  # get some parameters \n  nMax_PreviousSequenceTruths <- length(grep(names(res_mat),pattern=\"PreviousSequenceTruth_l\", value = T))\n  nMax_FutureTruth <- length(grep(names(res_mat),pattern=\"^Truth_l\", value = T))\n  \n  # create aggregate measures across model_id (based on modelingStrategyNameKey, unique for each grid entry)\n  # note: model_id is unique within grid rows; confirm via: \n  # table((res_mat[which(res_mat$model_id==res_mat$model_id[1]),])$ModelType)\n  # table((res_mat[which(res_mat$model_id==res_mat$model_id[1]),])$ModelDims)\n  res_mat$master_conditioning_id <- paste0(res_mat$model_id,\n                                           \"_\", res_mat$i_in_sgd)\n  table(table(res_mat$master_conditioning_id))\n\n  # process baselines \n  if(FALSE){\n  # future.apply version -> hurts memory \n  options(future.globals.maxSize = 26000 * 1024^2) # Set to 7 GB\n  #DT_skill <- future.apply::future_lapply(1:nrow(res_mat), # parallelize, but memory problems\n  DT_skill <- lapply(1:nrow(res_mat),\n                              function(zer){ \n                                #if(zer %% 1000 == 0){ print2(sprintf(\"At %s of %s [%.2f%%]\",zer, nrow(res_mat), 100*zer/nrow(res_mat))) } \n                                if(zer %% 1000 == 0){ write.csv(c(zer, nrow(res_mat)), file = '~/Downloads/i_.csv') }\n                                res_mat_red <- res_mat[zer,]\n                                \n                                # sanity checks \n                                # mean(is.na(res_mat$PreviousSequenceTruth_l1))\n                                # hist(res_mat$PreviousSequenceTruth_l1)\n                                # grep(names(res_mat),pattern=\"PreviousSequenceTruth_\", value = T)\n                                # grep(names(res_mat),pattern=\"^Truth_l\", value = T)\n                                # grep(names(res_mat),pattern=\"^Pred_l\", value = T)\n                                # plot(unlist(res_mat_red[,paste0(\"PreviousSequenceTruth_l\",1:nMax_PreviousSequenceTruths)]))\n                                # plot(na.omit(unlist(res_mat_red[,paste0(\"PreviousSequenceTruth_l\",1:nMax_PreviousSequenceTruths)])))\n                                # plot(na.omit(unlist(res_mat_red[,paste0(\"Truth_l\",1:nMax_FutureTruth)])))\n                                \n                                # sanity confirm continuity -- YES \n                                # plot(c(na.omit(unlist(res_mat_red[,paste0(\"PreviousSequenceTruth_l\",1:nMax_PreviousSequenceTruths)])), na.omit(unlist(res_mat_red[,paste0(\"Truth_l\",1:nMax_FutureTruth)]))))\n                                \n                                pred_l_baselineVal <- na.omit(unlist(res_mat_red[,paste0(\"PreviousSequenceTruth_l\",\n                                                                                         1:nMax_PreviousSequenceTruths)]))\n                                pred_l_baselineVal <- pred_l_baselineVal[length(pred_l_baselineVal)]\n                                if(length(pred_l_baselineVal) == 0){ pred_l_baselineVal <- NA }\n                                l_true <- unlist(res_mat_red[,paste0(\"Truth_l\",1:nMax_FutureTruth)])\n                                pred_l_mean <- unlist(res_mat_red[,paste0(\"Pred_l\",1:nMax_FutureTruth)])\n                                \n                                RSS_baseline <-  (pred_l_baselineVal - l_true)^2\n                                RSS_pred <- (pred_l_mean - l_true)^2\n                                SliceSkill <- 1 - (0.01+RSS_pred^0.5) / (0.01+RSS_baseline^0.5)\n                                names(SliceSkill) <- paste(\"SliceSkillTime\",1:nMax_FutureTruth, sep = \"\")\n                                names(RSS_pred) <- paste(\"RSSPredTime\",1:nMax_FutureTruth, sep = \"\")\n                                names(RSS_baseline) <- paste(\"RSSBaselineTime\",1:nMax_FutureTruth, sep = \"\")\n                                return( c(RSS_baseline, RSS_pred, SliceSkill) )\n                              })\n  DT_skill <- as.data.frame(do.call(rbind, DT_skill))\n  # plot(res_mat$i_in_sgd[1:100], DT_skill$SliceSkillTime12 ) \n  # mean(colnames(res_mat) %in% colnames(DT_skill))\n  }\n\n  # vectorized version \n  if(TRUE){   \n    mem.maxVSize(96000) # -> forces swapping \n    #mem.maxVSize(36000)\n    DT <- as.data.table(res_mat)           # data.table is fast because of shallow copies\n    \n    ## ------------------------------------------------------------------\n    ## 1. Pull the three blocks of columns into dense matrices ------------\n    ## ------------------------------------------------------------------\n    prev_cols  <- grep(\"^PreviousSequenceTruth_l\",  names(DT), value = TRUE)\n    truth_cols <- grep(\"^Truth_l\",                  names(DT), value = TRUE)\n    pred_cols  <- grep(\"^Pred_l\",                   names(DT), value = TRUE)\n    \n    prev_mat  <- (as.matrix(DT[, ..prev_cols]))       # n \u00D7 P\n    truth_mat <- (as.matrix(DT[, ..truth_cols]))      # n \u00D7 H\n    pred_mat  <- (as.matrix(DT[, ..pred_cols]))       # n \u00D7 H\n    \n    H <- ncol(truth_mat)                            # number of forecast times\n    \n    ## ------------------------------------------------------------------\n    ## 2. One vector that holds \"y[t\u20111]\" for each row --------------------\n    ## ------------------------------------------------------------------\n    # index of last non\u2011NA element in each row\n    last_idx <- max.col(!is.na(prev_mat), ties.method = \"last\")\n    baseline_vec <- prev_mat[cbind(seq_len(nrow(prev_mat)), last_idx)]   # length = n\n    \n    ## replicate once; the next steps are pure BLAS\u2011level matrix ops\n    baseline_mat <- matrix(baseline_vec, nrow = nrow(prev_mat), ncol = H)\n    \n    ## ------------------------------------------------------------------\n    ## 3. Compute RSS and skill all at once ------------------------------\n    ## -------------",
    "-----------------------------------------------------\n    rss_base <- (baseline_mat - truth_mat)^2\n    rss_pred <- (pred_mat     - truth_mat)^2\n    \n    skill_mat <- 1 - (0.01 + sqrt(rss_pred)) / (0.01 + sqrt(rss_base))\n    \n    ## ------------------------------------------------------------------\n    ## 4. Assemble result ------------------------------------------------\n    ## ------------------------------------------------------------------\n    DT_skill <- cbind(\n      as.data.table(rss_base, keep.rownames = FALSE),\n      as.data.table(rss_pred, keep.rownames = FALSE),\n      as.data.table(skill_mat, keep.rownames = FALSE)\n    )\n    \n    setnames(DT_skill,\n             c(paste0(\"RSSBaselineTime\", 1:H),\n               paste0(\"RSSPredTime\",     1:H),\n               paste0(\"SliceSkillTime\",  1:H)))\n    \n    # add to the main table (shallow copy; fast)\n    #Sys.setenv(R_MAX_VSIZE = \"40Gb\")\n    #library(float);DT <- fl(DT); out <- fl(out)\n    #DT <- cbind(DT, DT_skill)\n    #rm(out)\n    #res_mat <- as.data.frame(DT)\n    # rm(DT)\n  }\n  \n  if(dim(res_mat)[1] != dim(DT_skill)[1]){ stop(\"dim(res_mat) != dim(res_mat) in RealPreprocess.R\") }\n  \n  # combine skill with res_mat - combined object takes up too much mem \n  # res_mat <- cbind(res_mat, DT_skill)\n  # rm(DT_skill);gc()\n  \n  # future.apply -> memory unsafe \n  if(FALSE){ \n  #res_mat_agg <- tapply(X = 1:nrow(res_mat), simplify = T, \n  res_mat_agg <- future.apply::future_tapply(X = 1:nrow(res_mat), \n                        INDEX = res_mat$master_conditioning_id, \n                        FUN = function(zer){ \n    if( any(zer %% 1000 == 0) ) { \n      write.csv(c( max(zer), nrow(res_mat)), file = \"~/Downloads/i_.csv\")\n      #print2(sprintf(\"At %s of %s [%.2f%%]\", max(zer), nrow(res_mat), 100*max(zer)/nrow(res_mat))) \n    } \n    res_mat_zer <- res_mat[zer,]\n    DT_skill_zer <- DT_skill[zer,]\n    RSS_baseline <- apply(DT_skill_zer[,paste(\"RSSBaselineTime\",1:nMax_FutureTruth, sep = \"\")],\n                          2, function(zr){ return(mean(clipAt(f2n(zr)),na.rm=T)) } )\n    RSS_pred  <- apply(DT_skill_zer[,paste(\"RSSPredTime\",1:nMax_FutureTruth, sep = \"\")], 2, \n                       function(zr){ return(mean(clipAt(f2n(zr)),na.rm=T)) } )\n    skill_vec <- 1 - (0.001+RSS_pred^0.5) / (0.001+RSS_baseline^0.5)\n    \n    # rename \n    names(skill_vec) <- paste(\"SkillTime\",1:length(skill_vec), sep = \"\")\n    names(RSS_pred) <- paste(\"RSSPredTime\",1:length(skill_vec), sep = \"\")\n    names(RSS_baseline) <- paste(\"RSSBaselineTime\",1:length(skill_vec), sep = \"\")\n    \n    # investigate PredBase_l -- what is it? \n    meta_data <- res_mat_zer[1,which(apply(res_mat_zer,2,function(z){length(unique(z))})==1)]\n    meta_data <- meta_data[,!grepl(colnames(meta_data),pattern=\"^PreviousSequenceTruth_l\")]\n    meta_data <- meta_data[,!grepl(colnames(meta_data),pattern=\"^SliceSkillTime\")]\n    meta_data <- meta_data[,!grepl(colnames(meta_data),pattern=\"^PredBase_l\")]\n    meta_data <- meta_data[,!grepl(colnames(meta_data),pattern=\"^Pred_l\")]\n    meta_data <- meta_data[,!grepl(colnames(meta_data),pattern=\"^RSSPredTime\")]\n    meta_data <- meta_data[,!grepl(colnames(meta_data),pattern=\"^RSSBaselineTime\")]\n    meta_data <- meta_data[,!grepl(colnames(meta_data),pattern=\"^Truth_l\")]\n    meta_data <- meta_data[,!grepl(colnames(meta_data),pattern=\"^location_id\")]\n    meta_data <- meta_data[,!grepl(colnames(meta_data),pattern=\"^time_anchor_id\")]\n    \n    # return package \n    ret_package <- t(unlist(c(unlist(meta_data), RSS_baseline, RSS_pred, skill_vec)))\n    return( list(list(ret_package)) )\n  }); print2(\"Done generating res_mat_agg!\")\n  \n  res_mat_dims <- unlist(lapply(res_mat_agg,function(l_){length(unlist(l_))}))\n  DominantDim <- names(table(res_mat_dims)[which.max(table(res_mat_dims))])\n  # table(res_mat_dims)\n  if(length(unique(res_mat_dims)) != 1){warning(\"In RealPreprocess.R: More than 1 dim here!\")}\n  # if(length(unique(res_mat_dims)) != 1){stop(\"In RealPreprocess.R: More than 1 dim here!\")}\n  res_mat_agg <- res_mat_agg[res_mat_dims==DominantDim] # drop files with off dims\n  # colnames((res_mat_agg[[ g_<-which(res_mat_dims == DominantDim)[1]] ][[1]]))\n  # colnames((res_mat_agg[[ b_<-which(res_mat_dims != DominantDim)[1] ]][[1]]))\n  # setdiff(colnames((res_mat_agg[[g_]][[1]])), colnames((res_mat_agg[[b_]][[1]]))) \n  # which(res_mat_dims != 56 )\n  # incongruent colnames: \n  # table(res_mat_dims)\n  # setdiff(colnames(res_mat_agg[res_mat_dims!=DominantDim][[1]][[1]]), colnames(res_mat_agg[res_mat_dims==DominantDim][[1]][[1]]))\n  res_mat_agg <- as.data.frame(do.call(rbind, unlist(res_mat_agg, recursive=F )))\n  #res_mat_agg <- as.data.frame(do.call(plyr::rbind.fill, res_mat_agg ))\n  }\n  # vectorized -> memory safe \n  if(TRUE){\n    ## --- 1.  Convert to data.table and add the ID ---------------------------\n    DT [ , master_conditioning_id := paste0(model_id, \"_\", i_in_sgd) ]\n    DT_skill[ , master_conditioning_id := DT$master_conditioning_id ]  # align rows\n    \n    ## --- 2.  Identify the columns we need -----------------------------------\n    rss_base_cols <- grep(\"^RSSBaselineTime\", names(DT_skill), value = TRUE)\n    rss_pred_cols <- grep(\"^RSSPredTime\",     names(DT_skill), value = TRUE)\n    \n    ## columns that are constant within a group\n    meta_cols <- setdiff(\n      names(DT),\n      c(grep(\"^PreviousSequenceTruth_l\", names(DT), value = TRUE),\n        grep(\"^SliceSkillTime\",          names(DT), value = TRUE),\n        grep(\"^Pred(Base|_l)\",           names(DT), value = TRUE),\n        grep(\"^RSS(Pred|Baseline)Time\",  names(DT), value = TRUE),\n        grep(\"^Truth_l\",                 names(DT), value = TRUE),\n        c(\"location_id\", \"time_anchor_id\"))\n    )\n    \n    ## --- 3.  Compute the group\u2011level means (RSS) ----------------------------\n    RSS_agg <- DT_skill[ ,\n                ",
    "         lapply(.SD, function(z) mean(clipAt(f2n(z)), na.rm = TRUE)),\n                         by   = master_conditioning_id,\n                         .SDcols = c(rss_base_cols, rss_pred_cols) ]\n    \n    ## --- 4.  Derive the SkillTime* columns ----------------------------------\n    H <- length(grep(\"^Truth_l\", names(DT)))          # number of forecast times\n    RSS_base_mat <- as.matrix(RSS_agg[ , ..rss_base_cols ])\n    RSS_pred_mat <- as.matrix(RSS_agg[ , ..rss_pred_cols ])\n    \n    skill_mat <- 1 - (0.001 + sqrt(RSS_pred_mat)) /\n                (0.001 + sqrt(RSS_base_mat))\n    \n    set(\n      RSS_agg,\n      j = paste0(\"SkillTime\", 1:H),\n      value = as.data.table(skill_mat)\n    )\n    \n    ## --- 5.  Attach the invariant meta\u2011data (first row of each group) -------\n    Meta_agg <- DT[ , .SD[1], by = master_conditioning_id, .SDcols = meta_cols ]\n    \n    ## --- 6.  Final aggregate table ------------------------------------------\n    Meta_agg$master_conditioning_id_META <- Meta_agg$master_conditioning_id\n    Meta_agg[, master_conditioning_id := NULL]\n    res_mat_agg <- merge(x = Meta_agg, by.x = \"master_conditioning_id_META\",   \n                         y = RSS_agg, by.y = \"master_conditioning_id\")\n    print2(\"Done generating res_mat_agg!\")\n  }\n  \n  # convert to data.frame and calculate agg skill\n  res_mat_agg <- as.data.frame(res_mat_agg)\n  res_mat_agg$AggSkill_internal <- rowMeans(cbind(f2n(res_mat_agg$SkillTime8),\n                f2n(res_mat_agg$SkillTime9),\n                f2n(res_mat_agg$SkillTime10),\n                f2n(res_mat_agg$SkillTime11),\n                f2n(res_mat_agg$SkillTime12)), na.rm = T)\n  \n  res_mat_agg_maxIters <- res_mat_agg[res_mat_agg$i_in_sgd==(f2n(res_mat_agg$nSGD)) ,]\n  \n  if(nrow(res_mat_agg_maxIters) > 0 & FALSE){ \n    # sanity checks - exploring data qualitatively \n    tapply(f2n(res_mat_agg_maxIters$AggSkill_internal),res_mat_agg_maxIters$model_tex_loc,summary)\n    tapply(f2n(res_mat_agg_maxIters$AggSkill_internal),res_mat_agg_maxIters$paddingMethod,summary)\n    (tmp_<-tapply(f2n(res_mat_agg_maxIters$AggSkill_internal),res_mat_agg_maxIters$i_in_sgd, summary2))[order(f2n(names(tmp_)))]\n    # plot(f2n(names(do.call(rbind,tmp_)[,'Mean'])), do.call(rbind,tmp_)[,'Mean'])\n    (tmp_ <- tapply(f2n(res_mat_agg_maxIters$AggSkill_internal),res_mat_agg_maxIters$atEpoch, summary2))[ order(f2n(names(tmp_))) ] \n    (tmp_ <- tapply(f2n(res_mat_agg_maxIters$AggSkill_internal),res_mat_agg_maxIters$dataInputs, summary2))[\n                    order(unlist(lapply(tmp_,function(l_){l_[4]})),na.last = F) ]\n    (tmp_ <- tapply(f2n(res_mat_agg_maxIters$AggSkill_internal),\n                    paste(res_mat_agg_maxIters$dataInputs,\n                          res_mat_agg_maxIters$i_in_sgd,res_mat_agg_maxIters$evaluationTime,sep=\"_\"), \n                    summary2))[ order(unlist(lapply(tmp_,function(l_){l_[4]}))) ]\n    (tmp_ <- tapply(f2n(res_mat_agg_maxIters$AggSkill_internal),res_mat_agg_maxIters$ModelDepth, summary2))[ order(f2n(names(tmp_)),na.last = F) ]\n    tapply(f2n(res_mat_agg_maxIters$AggSkill_internal),res_mat_agg_maxIters$evaluationTime, summary2)\n    (tmp_<-tapply(f2n(res_mat_agg_maxIters$AggSkill_internal),res_mat_agg_maxIters$ContextLength, summary2))[order(f2n(names(tmp_)))]\n    # View(sort(tapply(f2n(res_mat_agg$SkillTime10),res_mat_agg$dataInputs, mean)))\n    \n    # looking at some predictions \n    res_mat_MaxIterOnly <- res_mat_orig[res_mat_orig$i_in_sgd==(res_mat_orig$nSGD),]\n    #res_mat_MaxIterOnly <- res_mat_orig[res_mat_orig$i_in_sgd==min(res_mat_orig$i_in_sgd),]\n    par(mfrow=c(2,2));for(irr in sample(1:nrow(res_mat_MaxIterOnly),2*2)){\n      plot(unlist(res_mat_MaxIterOnly[irr,paste0(\"Truth_l\",1:nMax_FutureTruth)]),ylim = c(0,4), \n           main = paste0(\"MD\",res_mat_MaxIterOnly$ModelDepth[irr],\"_\",\n                         \"CL\",res_mat_MaxIterOnly$ContextLength[irr],\"_\",\n                         res_mat_MaxIterOnly$i_in_sgd[irr]))\n      points(unlist(res_mat_MaxIterOnly[irr,paste0(\"Pred_l\",1:nMax_FutureTruth)]),pch=\"^\")\n    }\n    par(mfrow=c(1,1));\n    \n    hist(res_mat_agg_maxIters$AggSkill_internal[res_mat_agg_maxIters$AggSkill_internal>0])\n    # View(res_mat_agg_maxIters[res_mat_agg_maxIters$AggSkill_internal>0,])\n    \n    tapply(res_mat_agg[res_mat_agg$i_in_sgd==(f2n(res_mat_agg$nSGD)),]$SkillTime11,\n           res_mat_agg[res_mat_agg$i_in_sgd==(f2n(res_mat_agg$nSGD)),]$floatType,summary)\n    tapply(f2n(res_mat_agg[res_mat_agg$i_in_sgd==(f2n(res_mat_agg$nSGD)),]$te_grads),\n           res_mat_agg[res_mat_agg$i_in_sgd==(f2n(res_mat_agg$nSGD)),]$floatType,summary)\n  }\n  \n  # coercing to numeric\n  res_mat_agg[,paste0(\"SkillTime\",1:nMax_FutureTruth)] <- \n    apply(res_mat_agg[,paste0(\"SkillTime\",1:nMax_FutureTruth)],  2, f2n)\n  res_mat_agg[,paste0(\"RSSBaselineTime\",1:nMax_FutureTruth)] <- \n    apply(res_mat_agg[,paste0(\"RSSBaselineTime\",1:nMax_FutureTruth)],  2, f2n)\n  res_mat_agg[,paste0(\"RSSPredTime\",1:nMax_FutureTruth)] <- \n    apply(res_mat_agg[,paste0(\"RSSPredTime\",1:nMax_FutureTruth)],  2, f2n)\n  \n  tapply( res_mat_agg[res_mat_agg$i_in_sgd==max(res_mat_agg$i_in_sgd),]$SkillTime11,\n          res_mat_agg[res_mat_agg$i_in_sgd==max(res_mat_agg$i_in_sgd),]$evaluationTime, summary)\n  hist(res_mat_agg$SkillTime11,xlim = c(-10,1))\n  \n  tapply( res_mat_agg[res_mat_agg$i_in_sgd==max(res_mat_agg$i_in_sgd),]$SkillTime11,\n          res_mat_agg[res_mat_agg$i_in_sgd==max(res_mat_agg$i_in_sgd),]$dataInputs, summary)\n  tapply( res_mat_agg[res_mat_agg$i_in_sgd==max(res_mat_agg$i_in_sgd),]$SkillTime11,\n          grepl(res_mat_agg[res_mat_agg$i_in_sgd==max(res_mat_agg$i_in_sgd),]$dataInputs,\n                pattern= \"sqrt\"), summary)\n  \n  print2(\"Done with RealPreprocessing.R\")\n}\n"
  ),
  `ResultsAnalyze/SuperLModel_GenFigs.R` = paste0(
    "# Content of SuperLModel_GenFigs.R\n{\n  options(error = NULL)\n  # install.packages( \"~/Documents/helpeRs-software/helpeRs\",repos = NULL, type = \"source\",force = F)\n  print(\"Starting SuperLModel_GenFigs.R\")\n\n  print(\"Define data to use in analysis\")\n  #SimMode<-FALSE;AnalysisName <- \"RealApril15\";resultsFolder<-sprintf(\"./SavedResults/Real/Results_%s\",AnalysisName); FiguresTag <- \"RealTag\"; TheGrid <- as.data.frame( data.table::fread( sprintf(\"./Data/RunGrids/RealGrids/RealGrid_%s.csv\",AnalysisName) ) ) \n  #SimMode<-FALSE;AnalysisName <- \"RealApril15-2000iters\";resultsFolder<-sprintf(\"./SavedResults/Real/Results_%s\",AnalysisName); FiguresTag <- \"RealTag\"; TheGrid <- as.data.frame( data.table::fread( sprintf(\"./Data/RunGrids/RealGrids/RealGrid_%s.csv\",strsplit(AnalysisName, split=\"-\")[[1]][1]) ) ) \n  \n  SimMode<-TRUE;AnalysisName <- \"BigSimsJuly15\";resultsFolder<-sprintf(\"./SavedResults/Sim/Results_%s\",AnalysisName); FiguresTag <- \"SimTag\"; TheGrid <- as.data.frame( data.table::fread( theFileName <- sprintf(\"./Data/RunGrids/SimGrids/SimGrid_%s.csv\",strsplit(AnalysisName, split=\"-\")[[1]][1]) ) )\n  #SimMode<-TRUE;AnalysisName <- \"BigSimsApril15-9000iters\";resultsFolder<-sprintf(\"./SavedResults/Sim/Results_%s\",AnalysisName); FiguresTag <- \"SimTag\"; TheGrid <- as.data.frame( data.table::fread( theFileName <- sprintf(\"./Data/RunGrids/SimGrids/SimGrid_%s.csv\",strsplit(AnalysisName, split=\"-\")[[1]][1]) ) )\n  \n  print(\"Starting: --Load in and preprocess--\")\n  {\n    # helper imports\n    library(dplyr);library(data.table)\n    #floatType <- \"32\";force2GPU <- TRUE; source(\"./Analysis/SetupEnv/SuperLModel_MasterImports.R\")\n    ndm_source_extracted(\"SetupEnv/SuperLModel_helperFxns.R\")\n    \n    # other key hyperparameters\n    SaveFolder <- get0(\"SaveFolder\", inherits = TRUE, ifnotfound = \"./Figures/\")\n    dir.create(SaveFolder, recursive = TRUE, showWarnings = FALSE)\n    cexAxis <- 1.5; cexLab <- 2; cexMain = 2\n    \n    # load csvs\n    print2(\"---Loading in csv's---\")\n    library(future.apply); plan(multisession(workers = 10L)) # plan() is needed to set up multicore use \n    dt_list <- future.apply::future_lapply(\n                    grep(list.files(resultsFolder), pattern=\"\\\\.csv\",value=T), \n                          function(csv_file_){ \n                        data.table::fread(sprintf(\"%s/%s\", resultsFolder, csv_file_))})\n    future::plan(sequential)   # go back to a single process\n    res_mat <- data.table::rbindlist(dt_list, fill = TRUE)\n    dim(res_mat <- as.data.frame( res_mat ))\n    # colnames(res_mat) <- gsub(colnames(res_mat),pattern=\"Week\",replace=\"Time\")\n    \n    table(res_mat$i_in_sgd)\n    # res_mat <- res_mat[res_mat$i_in_sgd <= 28125,]\n    \n    # generate pair id \n    res_mat$PairID_recon <- paste(\n                             as.character(res_mat$BaseID), \n                             as.character(res_mat$i_in_sgd), \n                             as.character(res_mat$nSamplesTrain), \n                             as.character(res_mat$ModelDepth), \n                             as.character(res_mat$ModelDims), sep = \"_\")\n    # res_mat <- res_mat[1:100000,]\n    #table(res_mat$OSSType)\n    \n    # sanity checks \n    # table(res_mat$i_in_sgd)\n    # length(unique( res_mat$sim_index ) ) ; length(unique( res_mat$BaseID ) ) \n    # (table(res_mat$nSamplesTrain))\n    \n    # preprocessing \n    if(SimMode){  nTimesLookValidationInferenceTrainedTo <- 12L; nTimesLookValidationInference <- 50L }\n    if(!SimMode){ \n      print2(\"---Pre-processing Real csv's (individ -> agg)---\")\n      res_mat_orig <- res_mat\n      nTimesLookValidationInferenceTrainedTo <- nTimesLookValidationInference <- 12L \n      ndm_source_extracted(\"ResultsAnalyze/SuperLModel_GenFigs_RealPreprocess.R\")\n      res_mat <- res_mat_agg # override individual with agg results \n    } \n    \n    # create summary measures\n    StartTime_SkillSummary <- round(nTimesLookValidationInferenceTrainedTo*0.75)\n    res_mat$SkillSummary <- rowMeans(res_mat[,paste0(\"SkillTime\",StartTime_SkillSummary : nTimesLookValidationInferenceTrainedTo)], na.rm=T)\n    res_mat$RSSBaselineSummary <- rowMeans(res_mat[,paste0(\"RSSBaselineTime\",StartTime_SkillSummary : nTimesLookValidationInferenceTrainedTo)], na.rm=T)\n    res_mat$RSSPredSummary <- rowMeans(res_mat[,paste0(\"RSSPredTime\",StartTime_SkillSummary : nTimesLookValidationInferenceTrainedTo)], na.rm=T)\n    \n    # save to disk for shiny app \n    data.table::fwrite(res_mat, file = sprintf(\"~/Downloads/%s.csv\", ifelse(SimMode, yes = \"res_mat_sim\",no = \"res_mat_real\")))\n  }\n  \n  print(\"Some initial analyses\")\n  {\n    # subset last itter \n    res_mat_ <- res_mat[res_mat$i_in_sgd == max(res_mat$i_in_sgd),]\n    print(sprintf(\"---Marginal skill at training's end at week 11 with matrix dimensions %s---\", nrow(res_mat_)))\n    print( tapply(res_mat_$SkillTime11,res_mat_$ModelType,summary) ) \n    #print(tapply(res_mat_$SkillTime11,res_mat_$ModelType,function(x){plot(ecdf(x))}))\n    \n    # quick check of perf\n    myForest_ <- randomForest::randomForest(\n      y = res_mat_$SkillSummary, \n      x = res_mat_[,setdiff(paste0(colnames(TheGrid),\"\"), \"BaseID\")])\n    myForest_$importance[order(myForest_$importance),]\n    #tapply(res_mat_$SkillSummary,res_mat_$initialNormType,summary)\n    #tapply(res_mat_$SkillSummary,res_mat_$nSamplesTrain,summary)\n    #tapply(res_mat_$SkillSummary,res_mat_$initialTransform,summary)\n    #tapply(res_mat_$SkillSummary,res_mat_$ModelType,summary)\n    #tapply(res_mat_$SkillSummary,res_mat_$dataInputs,summary)\n    \n    # variable transformations \n    res_mat$nParamsModel_log <- log(f2n(res_mat$nParamsModel), base = 10)\n    res_mat$nSamplesTrain_log <- log(f2n(res_mat$nSamplesTrain), base = 10)\n    res_mat$i_in_sgd_log <- log(f2n(res_mat$i_in_sgd), base = 10)\n    res_mat$atEpoch_log <- log(f2n(res_mat$atEpoch), base = 10)",
    "\n    res_mat$ContextLength_log <- log(f2n(res_mat$ContextLength), base = 2)\n    res_mat$ModelDepth_log <- log(f2n(res_mat$ModelDepth), base = 2)\n    res_mat$ModelDims_log <- log(f2n(res_mat$ModelDims), base = 2)\n    res_mat$TimesSeen      <- f2n(res_mat$ContextLength) * f2n(res_mat$nSamplesTrain)\n    res_mat$TimesSeen_log  <- log10(res_mat$TimesSeen)\n    res_mat$UpdatesPerParam <- res_mat$i_in_sgd / res_mat$nParamsModel\n    res_mat$UpdatesPerParam_log <- log10(res_mat$UpdatesPerParam)\n    res_mat$DataParamRatio             <- res_mat$nSamplesTrain / res_mat$nParamsModel\n    res_mat$DataParamRatio_log10       <- log10(res_mat$DataParamRatio)\n    \n    Map2ConstrainedSkill <- function(x){ 1 - exp(x) }\n    InvMap2ConstrainedSkill <- function(x){ -log( (1 - x)+0.001  ) }\n    InvMap2ConstrainedSkill( 1)\n    \n    # plot(InvMap2ConstrainedSkill(x<-rnorm(100)),x)\n    \n    res_mat$SkillSummary_inv <- InvMap2ConstrainedSkill(res_mat$SkillSummary)\n    cor(res_mat$SkillSummary, res_mat$SkillSummary_inv)\n    # plot(res_mat$SkillSummary, res_mat$SkillSummary_inv)\n    max(Map2ConstrainedSkill(InvMap2ConstrainedSkill(res_mat$SkillSummary)) - res_mat$SkillSummary)\n    \n    #Map2ConstrainedBaselineRSS <- function(x){ exp(x) }\n    #InvMap2ConstrainedBaselineRSS <- function(x){ log( x )  }\n    \n    Map2ConstrainedBaselineRSS <- function(x) { ifelse(x > 20, x, log1p(exp(x))) }\n    InvMap2ConstrainedBaselineRSS <- function(y) { log(expm1(y)) }\n    \n    res_mat$RSSBaselineSummary_inv <- InvMap2ConstrainedBaselineRSS(res_mat$RSSBaselineSummary)\n    max(Map2ConstrainedBaselineRSS(InvMap2ConstrainedBaselineRSS(res_mat$RSSBaselineSummary)) - res_mat$RSSBaselineSummary)\n    \n    # sanity - this should yield *two*'s as each pair entry is used twice \n    if( any( tapply(as.character(res_mat_$model_tex_loc),\n           res_mat_$PairID_recon, table) ) > 2 ){\n      stop(\"Stopping: Some PairIDs are tripliced; REQUIRE 2 per only\")\n    }\n    print(\"Starting: --Done with load in and preprocess--\")\n  }\n  \n  print(\"Plotting comparision for skill results\") # paired by PairID_recon, with pairing by ModelType\n  {\n    print2(\"---Starting pairwise comparisions (Decoder vs. NeuralODE)---\")\n    library(dplyr); library(ggplot2)\n    \n    # Keep only the final iteration (or whichever iteration you care about)\n    res_mat_forpair <- res_mat#[res_mat$i_in_sgd == min(res_mat$i_in_sgd), ]\n    # note: individual results should be overridden with aggregate results in Real case\n    \n    # Subset by model types you want to compare: e.g., Transformer vs. NeuralODE\n    res_decoder   <- subset(res_mat_forpair, \n                            ModelType == \"DecoderOnly\")\n    res_neuralODE <- subset(res_mat_forpair, \n                            ModelType == \"NeuralODE\")\n    \n    # Merge so each row has both Decoder skill & NeuralODE skill, matched by PairID\n    # for real data anlaysis - do more merging before this step  \n\n    # memory issues here # -> should yeild ONE (one data entry per merged pair)\n    table(table(res_decoder$PairID_recon) )\n    table(table(res_neuralODE$PairID_recon))\n\n    # merge data \n    print2(\"---Merging pairwise (Decoder vs. NeuralODE)---\")\n    paired_df <- merge(\n      res_decoder, \n      res_neuralODE,\n      by = \"PairID_recon\", \n      suffixes = c(\"_Decoder\", \"_NeuralODE\")\n    )\n    # -> should be close to 1\n    if( mean(res_decoder$PairID_recon %in% res_neuralODE$PairID_recon) < 0.10){\n      stop(\"Not enough overlap between PairID_recon in Decoder vs. NeuralODE -- Check code!\")\n    }\n    head(cbind(sort(res_decoder$PairID_recon)[1:5],sort(res_neuralODE$PairID_recon)[1:5]))\n        \n    #plot(paired_df$SkillSummary_Decoder, paired_df$SkillSummary_NeuralODE,\n         #xlim = c(-1,1), ylim = c(-1,1)); abline(a=0,b=1)\n    \n    # Now make a scatterplot comparing the skills\n    print2(\"---Comparision scatterplots - Decoder vs. NeuralODE---\")\n    {\n    gsvs <- ggplot(paired_df[paired_df$i_in_sgd_Decoder==max(paired_df$i_in_sgd_Decoder),],\n      aes(x = SkillSummary_Decoder, y = SkillSummary_NeuralODE)) +\n      geom_point(alpha = 0.7) +\n      geom_abline(slope = 1, intercept = 0, color = \"red\", linetype = \"dashed\") +\n      theme_minimal(base_size = 14,\n                    base_line_size = 0) +\n      labs(\n        title = \"Comparison of Skill Index: Decoder vs NeuralODE\",\n        x = \"Skill Index (Decoder)\",\n        y = \"Skill Index (NeuralODE)\"\n      )\n    ggsave(sprintf(\"./Figures/gsvs_SimMode%s.pdf\", SimMode),\n           plot = gsvs, \n           device = \"pdf\", \n           width = 8, height = 8)\n  }\n    \n    # Define a binary outcome: 1 if Transformer skill is higher, 0 otherwise\n    paired_df$WinNeuralODE <- 1*(paired_df$SkillSummary_NeuralODE >= \n                                   paired_df$SkillSummary_Decoder)\n    \n    # generate win variable here \n    res_mat$WinNeuralODE_indicator <- paired_df$WinNeuralODE[\n      match(res_mat$PairID_recon, paired_df$PairID_recon)\n    ]\n    \n    # CDF PLOTs\n    i_seq <- NeuralWinProb <- c(); for(i___ in sort(unique(paired_df$i_in_sgd_Decoder)) ){ \n      \n      # 1. Gather all skill values\n      paired_df_ <- paired_df[paired_df$i_in_sgd_Decoder == i___,]\n      vals <- sort(unique(c(paired_df_$SkillSummary_Decoder, \n                            paired_df_$SkillSummary_NeuralODE)))\n      \n      # 2. Compute empirical CDF for Decoder and NeuralODE\n      decoder_cdf   <- sapply(vals, function(v) mean(paired_df_$SkillSummary_Decoder <= v))\n      neuralode_cdf <- sapply(vals, function(v) mean(paired_df_$SkillSummary_NeuralODE <= v))\n      \n      ks_stat <- ks.test(x = paired_df_$SkillSummary_Decoder, \n                         y = paired_df_$SkillSummary_NeuralODE,\n                         alternative = \"two.sided\")\n      print2( ks_stat$p.value) \n      \n      # append\n      i_seq <- c(i_seq,i___)\n      NeuralWinProb <- c(NeuralWinPro",
    "b,\n                         mean(paired_df_$SkillSummary_NeuralODE >= paired_df_$SkillSummary_Decoder))\n      \n      # 3. Combine into data frame\n      cdf_df <- data.frame(\n        value         = vals,\n        DecoderCDF    = decoder_cdf,\n        NeuralODECDF  = neuralode_cdf\n      )\n      \n      # 4. Plot CDF vs CDF\n      gcdfcdf <- ggplot(cdf_df, aes(x = DecoderCDF, y = NeuralODECDF)) +\n        geom_line(color = \"blue\", size = 1) +\n        # Draw the diagonal line (same distribution = x = y)\n        geom_abline(slope = 1, intercept = 0, color = \"red\", linetype = \"dashed\") +\n        coord_fixed() +\n        theme_minimal(base_size = 14,\n                      base_line_size = 0) +\n        labs(\n          title = sprintf(\"P\u2013P (CDF-vs-CDF) plot: Decoder vs NeuralODE (%s)\",i___),\n          subtitle = \"Below 45 degree line indicates better NeuralODE skill\",\n          x     = \"CDF(Decoder)\",\n          y     = \"CDF(NeuralODE)\"\n        )\n      ggsave(sprintf(\"./Figures/gcdfcdf_%s.pdf\",i___),\n             plot = gcdfcdf, \n             device = \"pdf\",\n             width = 8, height = 6)\n      \n      # Plot density of absolute skill for Decoder vs NeuralODE (dropping mean)\n      { \n      SkillSummary_ <- rbind(\"Decoder\" = summary(paired_df_$SkillSummary_Decoder)[-4],\n                             \"Neural ODE\" =summary(paired_df_$SkillSummary_NeuralODE)[-4]\n                             )\n      SkillSummary_[] <- helpeRs::fixZeroEndings(as.character(round(SkillSummary_[], 3)), 3)\n      latex_code <- capture.output(stargazer::stargazer(as.matrix(SkillSummary_),\n                                                        label = sprintf(\"tab:SkillSummarySimMode%s\",SimMode),\n                                                        font.size = \"small\",\n                                                        title = sprintf(\"\n                                                        Summary statistics of skill distributions for decoder-only and neural models.\n                                                                      %s\",\n                                                                        ifelse(SimMode, \n                                                                               yes = \"Case: simulation.\",\n                                                                               no = \"Case: COVID-19 analysis.\"))\n      ))\n      writeLines( latex_code,\n                  con = sprintf(\"./Figures/SkillSummaryTab_SimMode%s_i%s.tex\",SimMode, i___) )\n      }\n    }\n    writeLines( latex_code,\n                con = sprintf(\"./Figures/SkillSummaryTab_SimMode%s_i%s.tex\",SimMode, \"Final\") )\n    # pdfs to pdf \n    # https://www.coolutils.com/online/PDF-to-MP4\n    # reverse mp4\n    # https://www.online-convert.com/result#j=2c2ddf87-5ed3-46cb-8f12-6b7b59cc36f0\n    \n    # plot by iteration number \n    pdf(sprintf(\"./Figures/NeuralODEWinByIter_SimMode%s.pdf\",SimMode))\n    {\n    par(mar=c(5,5,5,1))\n    plot(\n      i_seq, NeuralWinProb,\n      type = \"p\", log = \"x\", pch = 19,\n      xlab = \"Iteration (log scale)\", ylab = \"Probability(NeuralODE Skill > Decoder)\",\n      main = \"NeuralODE vs Decoder\\nWin Probability by Iteration\",lwd = 2,\n      cex.lab = 1.75, cex.main = 1.75, \n      col  = \"black\", ylim = c(0.5-0.2,0.5+0.2)\n    )\n    fit <- lm(NeuralWinProb ~ log(i_seq))\n    abline(h=0.5, lty = 3, col = \"gray\", lwd = 2)\n    fit <- lm(NeuralWinProb ~ log(i_seq))\n    pred <- predict(fit, newdata = data.frame(i_seq = i_seq), interval = \"confidence\")\n    lines(i_seq, pred[,\"fit\"], col = \"red\", lwd = 2)\n    lines(i_seq, pred[,\"lwr\"], col = \"red\", lty = 2)\n    lines(i_seq, pred[,\"upr\"], col = \"red\", lty = 2)\n    }\n    dev.off()\n    \n    # plot by data size \n    # ---------------------------------------------------------------------------------\n    # NeuralODE vs\u00A0Decoder \u2011\u2011 Win probability by DATA\u2011SET SIZE\n    # ---------------------------------------------------------------------------------\n    {\n      print2(\"---NeuralODE vs Decoder win probability by DATA\u2011SET SIZE---\")\n      ## 1.  Keep only the final iteration for a clean comparison  --------------------\n      paired_df_EndOfTraining <- paired_df[paired_df$i_in_sgd_Decoder ==\n                                     max(paired_df$i_in_sgd_Decoder), ]\n      \n      ## 2.  Compute P( Skill_NeuralODE \u2265 Skill_Decoder ) for each nSamplesTrain ------\n      dsizes <- sort(unique(paired_df_EndOfTraining$nSamplesTrain_Decoder))\n      NeuralWinProb_ds <- sapply(\n        dsizes, function(ds) {\n          rows <- paired_df_EndOfTraining$nSamplesTrain_Decoder == ds\n          mean(paired_df_EndOfTraining$SkillSummary_NeuralODE[rows] >=\n                 paired_df_EndOfTraining$SkillSummary_Decoder[rows]) })\n      n_per_ds <- sapply(\n        dsizes, function(ds) sum(paired_df_EndOfTraining$nSamplesTrain_Decoder == ds))\n      se_      <- sqrt(NeuralWinProb_ds * (1 - NeuralWinProb_ds) / n_per_ds)\n      ci_low  <- pmax(0, NeuralWinProb_ds - 1.96 * se_)\n      ci_high <- pmin(1, NeuralWinProb_ds + 1.96 * se_)\n      \n      pdf(sprintf(\"./Figures/NeuralODEWinByDatasetSize_SimMode%s.pdf\",SimMode))\n      {\n      par(mar = c(5, 5, 5, 1))\n      plot(dsizes, NeuralWinProb_ds,\n           log      = \"x\",           # log\u2011scale x\u2011axis\n           type     = \"p\",\n           pch      = 19,\n           col      = \"black\",\n           ylim     = c(0.3, 0.9),\n           xlab     = \"Training Set Size\",\n           ylab     = \"Prob( NeuralODE Skill \u2265 Decoder )\",\n           main     = \"NeuralODE vs Decoder\\nWin Probability by Training Set Size\",\n           cex.lab  = 1.75,\n           cex.main = 1.75)\n      \n      ## Reference line at 0.5\n      abline(h = 0.5, lty = 3, col = \"gray\", lwd = 2)\n      \n      ## Error bars: SE\u2011based 95 % CIs\n      arrows(x0 = ",
    "dsizes, y0 = ci_low,\n             x1 = dsizes, y1 = ci_high,\n             angle = 90, code = 3, length = 0.05,\n             col = \"darkred\", lwd = 2)\n      }\n      dev.off()\n      \n      ##  Compute P( Skill_NeuralODE \u2265 Skill_Decoder ) for each per parameter update ------\n      val_ <- sort(unique(paired_df_EndOfTraining$UpdatesPerParam_Decoder))\n      NeuralWinProb_ds <- sapply(\n        val_, function(ds) {\n          rows <- paired_df_EndOfTraining$UpdatesPerParam_Decoder == ds\n          mean(paired_df_EndOfTraining$SkillSummary_NeuralODE[rows] >=\n                 paired_df_EndOfTraining$SkillSummary_Decoder[rows]) })\n      n_per_ds <- sapply(\n        val_, function(ds) sum(paired_df_EndOfTraining$UpdatesPerParam_Decoder == ds))\n      se_      <- sqrt(NeuralWinProb_ds * (1 - NeuralWinProb_ds) / n_per_ds)\n      ci_low  <- pmax(0, NeuralWinProb_ds - 1.96 * se_)\n      ci_high <- pmin(1, NeuralWinProb_ds + 1.96 * se_)\n      \n      pdf(sprintf(\"./Figures/NeuralODEWinByPerParamData_SimMode%s.pdf\",SimMode))\n      {\n        par(mar = c(5, 5, 5, 1))\n        plot(val_, NeuralWinProb_ds,\n             log      = \"x\",           # log\u2011scale x\u2011axis\n             type     = \"p\",\n             pch      = 19,\n             col      = \"black\",\n             ylim     = c(0, 1.1),\n             xlab     = \"Training Set Size\",\n             ylab     = \"Prob( NeuralODE Skill \u2265 Decoder )\",\n             main     = \"NeuralODE vs Decoder\\nWin Probability by Training Set Size\",\n             cex.lab  = 1.75,\n             cex.main = 1.75)\n        \n        ## Reference line at 0.5\n        abline(h = 0.5, lty = 3, col = \"gray\", lwd = 2)\n        \n        ## Error bars: SE\u2011based 95 % CIs\n        arrows(x0 = dsizes, y0 = ci_low,\n               x1 = dsizes, y1 = ci_high,\n               angle = 90, code = 3, length = 0.05,\n               col = \"darkred\", lwd = 2)\n      }\n      dev.off()\n      \n      # summarize\n      plot(tapply(paired_df_EndOfTraining$SkillSummary_Decoder,\n                  paired_df_EndOfTraining$ContextLength_Decoder,\n                  median))\n      plot(tapply(paired_df_EndOfTraining$SkillSummary_Decoder,\n                  paired_df_EndOfTraining$ModelDims_Decoder,\n                  median))\n      plot(tapply(paired_df_EndOfTraining$SkillSummary_Decoder,\n                  paired_df_EndOfTraining$nSamplesTrain_Decoder,\n                  median))\n      \n      # forests\n      #paired_df_EndOfTraining$SkillSummary_Decoder[paired_df_EndOfTraining$SkillSummary_Decoder < -4] <- -4\n      #paired_df_EndOfTraining$SkillSummary_NeuralODE[paired_df_EndOfTraining$SkillSummary_NeuralODE < -4] <- -4\n      DecoderForest <- randomForest::randomForest(\n        y = paired_df_EndOfTraining$SkillSummary_inv_Decoder, \n        x = paired_df_EndOfTraining[,setdiff(paste0(colnames(TheGrid),\"_Decoder\"), \n                                             c(\"BaseID_Decoder\",\"ResaveThisTFRecord_Decoder\"))])\n      DecoderImport <- DecoderForest$importance#[order(DecoderForest$importance),]\n      \n      NeuralODEForest <- randomForest::randomForest(\n        y = paired_df_EndOfTraining$SkillSummary_inv_NeuralODE, # inv \n        x = paired_df_EndOfTraining[,setdiff(paste0(colnames(TheGrid),\"_NeuralODE\"), \n                                             c(\"BaseID_NeuralODE\",\"ResaveThisTFRecord_NeuralODE\"))])\n      NeuralODEImport <- NeuralODEForest$importance#[order(NeuralODEForest$importance),]\n      \n      DiffForest <- randomForest::randomForest(\n        y = paired_df_EndOfTraining$SkillSummary_inv_NeuralODE - \n                    paired_df_EndOfTraining$SkillSummary_inv_Decoder, \n        x = paired_df_EndOfTraining[,setdiff(paste0(colnames(TheGrid),\"_Decoder\"), \n                                                   c(\"BaseID_Decoder\",\"ResaveThisTFRecord_Decoder\"))]\n        )\n      DiffImport <- DiffForest$importance#[order(NeuralODEForest$importance),]\n      DiffForest$importance[order(NeuralODEForest$importance),]\n      \n      if(FALSE){ \n        # split into short vs. long contexts at the median\n        med_ctx <- median(paired_df_EndOfTraining$ContextLength_Decoder)\n        for(grp in c(\"Short\",\"Long\")) {\n          df <- paired_df_EndOfTraining[\n            (grp==\"Short\" & paired_df_EndOfTraining$ContextLength_Decoder <  med_ctx) |\n              (grp==\"Long\"  & paired_df_EndOfTraining$ContextLength_Decoder >= med_ctx), ]\n          rf <- randomForest::randomForest(\n            y = df$SkillSummary_inv_NeuralODE - df$SkillSummary_inv_Decoder,\n            x = df[, setdiff(paste0(colnames(TheGrid),\"_Decoder\"),\n                             c(\"BaseID_Decoder\",\"ResaveThisTFRecord_Decoder\"))]\n          )\n          cat(\"\\nVariable importance for\", grp, \"contexts:\\n\")\n          print(rf$importance[order(rf$importance), , drop=FALSE])\n          # policy_effectiveness_Decoder\n        }  \n      }\n      \n      row.names(DiffImport) <- gsub(row.names(DiffImport), pattern = \"_Decoder\",replace=\"\")\n      row.names(DecoderImport) <- gsub(row.names(DecoderImport), pattern = \"_Decoder\",replace=\"\")\n      row.names(NeuralODEImport) <- gsub(row.names(NeuralODEImport), pattern = \"_NeuralODE\",replace=\"\")\n      mean(row.names(NeuralODEImport) == row.names(DecoderImport)) # == 1\n      plot(DecoderImport,NeuralODEImport); abline(a=0,b=1)\n      plot(DecoderImport,DiffImport); abline(a=0,b=1)\n      plot(NeuralODEImport,DiffImport); abline(a=0,b=1)\n      DecoderImport[order(DecoderImport),]\n      NeuralODEImport[order(NeuralODEImport),]\n      DiffImport[order(DiffImport),]\n      cor(cbind(DecoderImport, NeuralODEImport, DiffImport))\n      \n      # other figs \n      {\n      # 1. Bin axes (feel free to pick break widths that leave \u226520 pairs per bin)\n      paired_df_EndOfTraining$b_ctx <- as.factor(paired_df_EndOfTraining$ContextLength_Decoder)#cut(paired_df_EndOfTrain",
    "ing$ContextLength_Decoder,\n                             #breaks = 2^seq(0, log2(max(paired_df_EndOfTraining$ContextLength_Decoder)), by = 1),\n                             #right = FALSE)\n      paired_df_EndOfTraining$b_nsamp <- as.factor(paired_df_EndOfTraining$nSamplesTrain_Decoder)#cut(paired_df_EndOfTraining$nSamplesTrain_Decoder,\n                               #breaks = 10^seq(3, log10(max(paired_df_EndOfTraining$nSamplesTrain_Decoder)), by = 0.5),\n                               #right = FALSE)\n      \n      # 2. Aggregate win\u2011probability & gap\n      phase <- paired_df_EndOfTraining |>\n        group_by(b_ctx, b_nsamp) |>\n        summarise(p_win = mean(SkillSummary_NeuralODE >= SkillSummary_Decoder),\n                  gap   = median(abs(SkillSummary_NeuralODE - SkillSummary_Decoder)),\n                  n     = n(), .groups = \"drop\") |>\n        filter(n >= 20)                   # reliability filter\n      \n      # 3. Plot\n      p <- ggplot(phase, aes(x = b_ctx, y = b_nsamp, fill = p_win)) +\n        geom_tile() +\n        geom_contour(aes(z = p_win), breaks = 0.5, colour = \"black\",\n                     linetype = \"dashed\", size = 1.2) +\n        geom_text(aes(label = scales::percent(p_win, accuracy = 1)),\n                  colour = \"white\", size = 3) +\n        scale_fill_viridis_c(name = \"P(NeuralODE > Decoder)\",\n                             limits = c(0,1)) +\n        scale_x_discrete(expand = c(0,0)) +\n        scale_y_discrete(expand = c(0,0)) +\n        labs(title = \"When does NeuralODE beat a Decoder\u2011only model?\",\n             x = \"Context length\", y = \"Training-set size\") +\n        theme_minimal(base_size = 14) +\n        theme(axis.text.x = element_text(angle = 45, hjust = 1))\n      ggsave(p, \n             file = sprintf(\"./Figures/PhaseDiagram_NeuralODEvsDecoder_SimMode%s.pdf\",SimMode),\n             width = 8, height = 6)\n    }\n    }\n    \n    #-----------------------------------------------------------------------#\n    print2(\"---Logistic regression: Probability( NeuralODE wins | predictors )---\")\n    if(SimMode){\n    m_logit <- glm(\n      WinNeuralODE ~ \n        sigma_NeuralODE + \n        gamma_NeuralODE +\n        c_endogeneous_NeuralODE + \n        policy_effectiveness_NeuralODE +\n        ContextLength_NeuralODE + \n        nParamsModel_log_NeuralODE + \n        nSamplesTrain_log_NeuralODE,\n      data   = paired_df[paired_df$i_in_sgd_Decoder == max(paired_df$i_in_sgd_Decoder), ],\n      family = binomial(\"logit\")\n    )\n    summary(m_logit)\n    \n    # Predicted probabilities and AUC\n    paired_df$pred_prob_logit <- predict(m_logit, \n                                         newdata = paired_df, \n                                         type = \"response\")\n    roc_logit <- pROC::roc(paired_df$WinNeuralODE, \n                           paired_df$pred_prob_logit)\n    cat(\"AUC (Logistic) =\", round(pROC::auc(roc_logit), 3), \"\\n\")\n    table(paired_df$WinNeuralODE)\n    plot(paired_df$WinNeuralODE, paired_df$pred_prob_logit)\n    \n    # heat mappers \n    MakeHeatMap(  factor1 = c(\"log(Context length)\" = \"ContextLength_NeuralODE\"),\n                  factor2 = c(\"log(# of Samples)\" = \"nSamplesTrain_log_NeuralODE\"),\n                  outcome = \"WinNeuralODE\",\n                  pdf_path = sprintf(\"./Figures/Heat_Win.pdf\"),\n                  useLog = \"\", \n                  dat = (paired_df[paired_df$i_in_sgd_Decoder==max(paired_df$i_in_sgd_Decoder),\n                                   colnames(m_logit$model)]),\n                  lm_obj =  m_logit,\n                  extrap_factor1 = 1, extrap_factor2 = 1, \n                  OutcomeTransformFxn = function(x){e1071::sigmoid(x)}, \n                  openBrowser = F )\n    \n    # additional tests \n    { \n    test_ <- glm(\n      SkillSummary_NeuralODE ~ \n        floatType_NeuralODE+\n        sigma_NeuralODE + \n        gamma_NeuralODE +\n        c_endogeneous_NeuralODE + \n        policy_effectiveness_NeuralODE +\n        ContextLength_NeuralODE + \n        nParamsModel_log_NeuralODE + \n        nSamplesTrain_log_NeuralODE,\n      data   = paired_df[paired_df$i_in_sgd_NeuralODE == max(paired_df$i_in_sgd_NeuralODE), ],\n      family = 'gaussian'\n    )\n    \n    df_ <- paired_df[paired_df$i_in_sgd_NeuralODE == max(paired_df$i_in_sgd_NeuralODE), ]\n    myForest_NeuralODESkill <- randomForest::randomForest(\n                               y = df_$SkillSummary_NeuralODE, \n                               x = df_[,paste0(colnames(TheGrid),\"_NeuralODE\")])\n    myForest_NeuralODESkill$importance[order(myForest_NeuralODESkill$importance),]\n    \n    myForest_DiffSkill <- randomForest::randomForest(\n      y = df_$SkillSummary_Decoder-df_$SkillSummary_NeuralODE, \n      x = df_[,paste0(colnames(TheGrid),\"_NeuralODE\")])\n    myForest_DiffSkill$importance[order(myForest_DiffSkill$importance),]\n    \n    test_ <- glm(\n        SkillSummary_NeuralODE ~ \n        floatType_NeuralODE+\n        sigma_NeuralODE + \n        gamma_NeuralODE +\n        c_endogeneous_NeuralODE + \n        policy_effectiveness_NeuralODE +\n        ContextLength_NeuralODE + \n        nParamsModel_log_NeuralODE + \n        nSamplesTrain_log_NeuralODE,\n      data   = df_,\n      family = 'gaussian'\n    )\n    summary( test_ )\n    paired_df$floatType_NeuralODE\n    }\n    }\n    \n    {\n      # ----------------------------------------------------------------------\n      # Pretty scaling plot: context length  \u2715  # observations\n      # ----------------------------------------------------------------------\n      library(patchwork)   # side\u2011by\u2011side layouts\n      library(tidyr)\n      \n      ## 2.  Gather into long form -------------------------------------------\n      long_scaling <- paired_df_EndOfTraining |>\n        ## keep only the columns we need\n        dplyr::select(PairID_recon,\n                      ContextLength_Decoder, SkillSummary_Deco",
    "der,\n                      ContextLength_NeuralODE, SkillSummary_NeuralODE,\n                      nSamplesTrain_Decoder, SkillSummary_Decoder,\n                      nSamplesTrain_NeuralODE, SkillSummary_NeuralODE,\n                      #c_endogeneous_Decoder, c_endogeneous_NeuralODE,\n                      #policy_effectiveness_Decoder, policy_effectiveness_NeuralODE,\n                      ModelDims_Decoder, ModelDims_NeuralODE\n                      ) |>\n        ## reshape: names like ContextLength_log_Decoder \u2192 value = ContextLength_log, Model\n        pivot_longer(\n          cols      = -PairID_recon,\n          names_to  = c(\".value\", \"Model\"),      # the bit before the final underscore is the \".value\"\n          names_sep = \"_(?=[^_]+$)\"              # split on the last underscore\n        ) |>\n        ## nicer labels\n        mutate(Model = factor(Model,\n                              levels = c(\"Decoder\", \"NeuralODE\"),\n                              labels = c(\"Decoder\", \"NeuralODE\")))\n      \n      ## 3.  Plot helpers -----------------------------------------------------\n      base_theme <- theme_minimal(base_size = 14) +\n        theme(panel.grid.major  = element_line(size = 0.3),\n              panel.grid.minor  = element_blank(),\n              legend.position   = \"bottom\")\n      pal <- c(\"Decoder\"   = \"#e64b35\",   # deep red\n               \"NeuralODE\" = \"#4da6ff\")   # sky blue\n      \n      ## 4.  Panel A \u2013 scaling in context length -----------------------------\n      lowess_span <- 5\n      p_context <- ggplot(long_scaling,\n                          aes(x = ContextLength,\n                              y = SkillSummary,\n                              colour = Model)) +\n        geom_point(alpha = .65, size = 1.5) +\n        geom_smooth(se = FALSE, method = \"loess\",\n                    span = lowess_span, linewidth = 1.2) +\n        scale_colour_manual(values = pal, \n                            breaks = c(\"Decoder\", \"NeuralODE\"),   # legend top -> bottom\n                            name = NULL) +\n        guides(colour = guide_legend(nrow = 2, byrow = TRUE)) + \n        scale_x_continuous(\n          trans  = scales::log2_trans(),          # base\u20112 log transform\n          breaks = scales::trans_breaks(\"log2\", function(x) 2^x),\n          labels = scales::trans_format(\"log2\", scales::math_format(2^.x))\n        ) +\n        #scale_y_continuous(\n          #limits = c(-1, 1),\n          #oob    = scales::oob_squish )+         # puts anything < \u20130.5 right on \u20130.5\n        coord_cartesian(ylim = c(-0.5, 1)) + \n        labs(x = \"log(Context length)\",\n             y = \"Skill index\",\n             title = \"A. Scaling with context length\") +\n        base_theme\n      \n      ## 5.  Panel B \u2013 scaling in # observations -----------------------------\n      p_nsamp <- ggplot(long_scaling,\n                        aes(x = nSamplesTrain,\n                            y = SkillSummary,\n                            colour = Model)) +\n        geom_point(alpha = .65, size = 1.5) +\n        geom_smooth(se = FALSE, method = \"loess\", \n                    span = lowess_span, linewidth = 1.2) +\n        scale_colour_manual(values = pal,\n                            breaks = c(\"Decoder\", \"NeuralODE\"),   # legend top -> bottom\n                            name = NULL) +\n        guides(colour = guide_legend(nrow = 2, byrow = TRUE)) + \n        labs(x = \"Training-set size\",\n             y = NULL,\n             title = \"B. Scaling with number of observations\") +\n        base_theme +\n        scale_x_continuous(\n          trans  = scales::log10_trans(),          # base\u201110 log transform\n          breaks = scales::trans_breaks(\"log10\", function(x) 10^x),\n          labels = scales::trans_format(\"log10\", scales::math_format(10^.x))\n        ) +\n        #scale_y_continuous(\n          #limits = c(-1, 1),\n          #oob    = scales::oob_squish )+         # puts anything < \u20130.5 right on \u20130.5\n        coord_cartesian(ylim = c(-0.5, 1)) + \n        theme(axis.text.y = element_blank(),\n              axis.ticks.y = element_blank())\n      \n      ## Panel C \u2013   ------------------------------------------\n      p_ <- ggplot(long_scaling,\n                    aes(x = ModelDims, y = SkillSummary, colour = Model)) +\n        geom_point(alpha = .65, size = 1.5) +\n        geom_smooth(se = FALSE, \n                    method = \"loess\", \n                    span = lowess_span, linewidth = 1.2) +\n        scale_colour_manual(values = pal,\n                            limits = c(\"Decoder\", \"NeuralODE\"),   # legend top \u2192 bottom\n                            name   = NULL) +\n        guides(colour = guide_legend(nrow = 2, byrow = TRUE)) +\n        scale_x_continuous(\n          trans  = scales::log10_trans(),          # base log transform\n          breaks = scales::trans_breaks(\"log2\", function(x) 2^x),\n          labels = scales::trans_format(\"log2\", scales::math_format(2^.x))\n        ) +\n        #scale_y_continuous(\n          #limits = c(-1, 1),\n          #oob    = scales::oob_squish ) +         # puts anything < \u20130.5 right on \u20130.5\n        coord_cartesian(ylim = c(-0.5, 1)) + \n        labs(x = \"\",\n             y = NULL,\n             title = \"C. Model Dimensions\") +\n        base_theme +\n        theme(axis.text.y  = element_blank(),\n              axis.ticks.y = element_blank())\n      \n      ## 6.  Assemble & write -------------------------------------------------\n      scaling_plot <- (p_context | p_nsamp | p_) +  \n                          plot_layout(guides = \"collect\")\n      scaling_plot\n      ggsave(sprintf(\"./Figures/Scaling_Decoder_vs_NeuralODE_%s.pdf\",SimMode),\n             scaling_plot, device = \"pdf\",\n             width = 10, height = 5)\n    }\n    print(\"Done plotting comparision for skill results...\") \n  }\n  \n  print(\"",
    "source the scaling results\")\n  ndm_source_extracted(\"ResultsAnalyze/SuperLModel_GenScalingResults.R\")\n\n  print(\"source the input stats\")\n  ndm_source_extracted(\"ResultsAnalyze/SuperLModel_GenFigs_GenInputStats.R\")\n  \n  Decoder_ <- res_mat_[res_mat_$ModelType==\"DecoderOnly\",]\n  NeuralODE <- res_mat_[res_mat_$ModelType==\"NeuralODE\",]\n  \n  print(\"Results evolution figs\")\n  { \n    # heat map analyses \n    GroupPolicyResultsBy_cols <- c(\"ContextLength\",\"ModelDepth\",\"nSamplesTrain\")\n    res_mat$GroupPolicyResultsBy <- apply(res_mat[,GroupPolicyResultsBy_cols],\n                                          1, function(x){ paste(x,collapse = \"_\") })\n    # table(res_mat$GroupPolicyResultsBy)\n    \n    # initialization analysis \n    res_mat_Start <- res_mat[res_mat$i_in_sgd %in% min(res_mat$i_in_sgd),]\n    res_mat_End <- res_mat[res_mat$i_in_sgd %in% (res_mat$nSGD),]\n    tapply(res_mat_End$SkillSummary, res_mat_End$ModelDepth, mean2)\n    \n    v_seq <- quantile(sort(unique(f2n(res_mat$i_in_sgd))),c(0,0.33,0.66,1))\n    v_seq <- sapply(v_seq,function(x){sort(unique(f2n(res_mat$i_in_sgd)))[\n                    which.min(abs(x-sort(unique(f2n(res_mat$i_in_sgd)))))]})\n    v_ct_ <- 0; for(v_ in v_seq){ \n      v_ct_ <- v_ct_ + 1 \n      pdf(file.path(SaveFolder, sprintf(\"SkillAnimation_%s_%s.pdf\", FiguresTag, v_ct_)))\n      par(mar=c(5,5,3,1))\n      hist( ifelse(f2n(res_mat[j_<-res_mat$i_in_sgd==v_,]$SkillSummary)<0,0,\n                   f2n(res_mat$SkillSummary)[j_]), xlim = c(0,1), \n            xlab = \"Skill\", ylab = \"Frequency\", cex.main = 2,cex.lab = 2, \n            breaks = seq(0,1,length.out=10),\n            main = sprintf(\"Iteration %s of %s\", v_, max(unique(f2n(res_mat$i_in_sgd)))))\n      dev.off()\n    }\n      \n    print2(\"---Baseline skill visualizations---\")\n    pdf(sprintf(\"./Figures/RSSBaseVSkillAtInitialization_%s.pdf\",FiguresTag))\n    {\n    par(mar=c(5,5,1,1), mfrow = c(1,1))\n    plot( res_mat_Start$RSSBaselineSummary,\n          ytrans_ <- -log(abs(res_mat_Start$SkillSummary)), \n          log = \"x\", yaxt = \"n\",\n          cex.lab = 1.5, \n          xlab = \"RSS Baseline\", \n          ylab = \"Skill at Initialization\")\n    axis(side = 2,\n         at = seq(summary(ytrans_)[1],\n                  summary(ytrans_)[6], length.out = 4), \n         labels = round(\n                  seq(summary(res_mat$SkillSummary)[1],\n                      summary(res_mat$SkillSummary)[6], \n                      length.out = 4), 2))\n    }\n    dev.off() \n    \n    pdf(sprintf(\"./Figures/RSSBaseline_c1_%s.pdf\",FiguresTag))\n    {\n    par(mfrow=c(2,2),mar=c(2,2,4,1))\n    theLims <- c(0,1.5*max(eval(parse(text = \n          sprintf(\"res_mat_Start$RSSBaselineTime%s\",\n                  nTimesLookValidationInferenceTrainedTo))), na.rm=T ))\n    for(f_ in 4:1){ \n    hist(eval(parse(text = \n                      sprintf(\"res_mat_Start$RSSBaselineTime%s\",\n                              wk_ <- round(nTimesLookValidationInferenceTrainedTo/f_) ))), \n         xlim= theLims,  \n         main = sprintf(\"RSS, Time %s\",wk_), xlab = \"\", cex.main = 1.5, \n         breaks = seq(0,theLims[2],length.out = 40))\n    }\n    }\n    dev.off()\n    \n    if(SimMode & T == F){ \n    for(GroupPolicyByThis_ in unique(res_mat$GroupPolicyResultsBy)){\n      for(ty_ in c(\"BaselineRSS\", \"Skill\")){\n      res_mat_ <- res_mat[res_mat$i_in_sgd %in% max(res_mat$i_in_sgd) & \n                           res_mat$GroupPolicyResultsBy %in% GroupPolicyByThis_,]\n      if(ty_ == \"Skill\"){ theOutcome <- \"SkillSummary\" } \n      if(ty_ == \"BaselineRSS\"){ theOutcome <- \"RSSBaselineSummary\" } \n      aggregated_data_median <- res_mat_ %>% group_by(c_endogeneous, policy_effectiveness) %>% \n        summarise(Ave = median(eval(parse(text=theOutcome))))\n      aggregated_data_median <- reshape2::acast(aggregated_data_median, c_endogeneous ~ policy_effectiveness, value.var=\"Ave\")\n      \n      aggregated_data_mean <- res_mat_ %>% group_by(c_endogeneous, policy_effectiveness) %>% summarise(Ave = mean(eval(parse(text=theOutcome))))\n      aggregated_data_mean <- reshape2::acast(aggregated_data_mean, c_endogeneous ~ policy_effectiveness, value.var=\"Ave\")\n      \n      aggregated_data_mean_clip <- res_mat_ %>% group_by(c_endogeneous, policy_effectiveness) %>% summarise(Ave = clippedMean(eval(parse(text=theOutcome))))\n      aggregated_data_mean_clip <- reshape2::acast(aggregated_data_mean_clip, c_endogeneous ~ policy_effectiveness, value.var=\"Ave\")\n      \n      aggregated_data_var <- res_mat_ %>% group_by(c_endogeneous, policy_effectiveness) %>% summarise(Ave = var(eval(parse(text=theOutcome))))\n      aggregated_data_var <- reshape2::acast(aggregated_data_var, c_endogeneous ~ policy_effectiveness, value.var=\"Ave\")\n  \n      aggregated_data_n <- res_mat_ %>% group_by(c_endogeneous, policy_effectiveness) %>% summarise(Ave = length(eval(parse(text=theOutcome))))\n      aggregated_data_n <- reshape2::acast(aggregated_data_n, c_endogeneous ~ policy_effectiveness, value.var=\"Ave\")\n      sum(aggregated_data_n, na.rm=T)\n      \n      aggregated_data_se <- sqrt( aggregated_data_var / aggregated_data_n)\n      aggregated_data_lb <- aggregated_data_mean - sqrt(1/aggregated_data_n * aggregated_data_var)\n  \n      RowKey <- c(\"Endo.\"); ColKey <- c(\"P. Effect\")\n      ProcessAggMatFxn <- function(m){\n        m[] <- helpeRs::fixZeroEndings(round(m,2))\n        row.names(m) <- helpeRs::fixZeroEndings(round(f2n(row.names(m)),3),roundAt=3)\n        colnames(m) <- helpeRs::fixZeroEndings(round(f2n(colnames(m)),3),roundAt=3)\n        row.names(m)[1] <- paste(sprintf(\"%s$=$\",RowKey), rownames(m)[1]); \n        colnames(m)[1] <- paste(sprintf(\"%s$=$\",ColKey), colnames(m)[1])\n        return(m)\n      }\n      GroupPolicyByThisText_ <- paste(sapply(1:length(GroupPolicyResultsBy_cols),\n                                       function(s_){ \n                ",
    "                       tmp_ <- res_mat[1,GroupPolicyResultsBy_cols][s_]\n                                       paste0(names(tmp_)[1],\"=\", \n                                              format(tmp_[1], scientific = FALSE))\n                                       }),collapse=\", \")\n      write(file = sprintf(\"%s/Heat%s_%s.tex\", SaveFolder, ty_, FiguresTag),\n            stargazer::stargazer(ProcessAggMatFxn(aggregated_data_mean), type = \"latex\", \n                                   label = sprintf(\"tab:Heat%s\", ty_), \n                                   title = sprintf(\"%s Rows denote endogeneity levels; columns denote policy effectiveness levels. \n                                                   %s. %s observations per grid cell.\",\n                                              ifelse(ty_ == \"BaselineRSS\", \n                                              yes = \"Baseline RSS analysis. \", \n                                              no = \"Skill analysis.\"), \n                                              GroupPolicyByThisText_,\n                                              theN <- median(aggregated_data_n) )))\n      write(file = sprintf(\"%s/Heat%sVar_%s.tex\", SaveFolder, ty_, FiguresTag),\n            stargazer::stargazer(ProcessAggMatFxn(aggregated_data_se), type = \"latex\", \n                                 label = sprintf(\"tab:Heat%sSE\", ty_), \n                                 title = sprintf(\"%s Rows denote endogeneity levels; columns denote policy effectiveness levels. \n                                                   %s. %s observations per grid cell.\",\n                                                 ifelse(ty_ == \"BaselineRSS\", \n                                                        yes = \"Baseline RSS analysis, standard error. \", \n                                                        no = \"Skill analysis, standard error.\"), \n                                                 GroupPolicyByThisText_,\n                                                 theN  )))\n    }\n    }\n    }\n  }\n  \n  stop(\"XXX\")\n  {\n    print(\"--- XXX12344321XXX: Generating 3 Powerful Insight Figures ---\")\n    {\n      library(ggplot2); library(dplyr)\n      \n      # 0. Setup: Filter for the final converged state\n      # We rely on paired_df created in the previous block; if missing, we use res_mat\n      if(exists(\"paired_df\")){\n        df_test <- paired_df[paired_df$i_in_sgd_Decoder == max(paired_df$i_in_sgd_Decoder), ]\n      } else {\n        # Fallback to creating a simple paired view from res_mat if paired_df is absent\n        df_test <- res_mat[res_mat$i_in_sgd == max(res_mat$i_in_sgd), ] %>%\n          filter(ModelType %in% c(\"DecoderOnly\", \"NeuralODE\")) %>%\n          tidyr::pivot_wider(names_from = ModelType, values_from = c(SkillSummary, RSSBaselineSummary)) %>%\n          rename(SkillSummary_Decoder = SkillSummary_DecoderOnly, \n                 SkillSummary_NeuralODE = SkillSummary_NeuralODE,\n                 RSSBaselineSummary_Decoder = RSSBaselineSummary_DecoderOnly)\n        names(df_test) <- paste0(names(df_test), \"_Decoder\") # Simplified suffixing for fallback\n      }\n      \n      # -------------------------------------------------------------------------\n      # FIG 1: MECHANISTIC SCALING LAWS (The Efficiency Test)\n      # Hypothesis: Hybrid has a steeper power-law exponent than Decoder.\n      # Transform: g(S) = -log(1 - Skill + epsilon) as per Paper Methods.\n      # -------------------------------------------------------------------------\n      df_test$g_Skill_Dec  <- -log(1 - df_test$SkillSummary_Decoder + 1e-3)\n      df_test$g_Skill_Node <- -log(1 - df_test$SkillSummary_NeuralODE + 1e-3)\n      #df_test$g_Skill_Dec  <- (df_test$SkillSummary_Decoder + 1e-3)\n      #df_test$g_Skill_Node <- (df_test$SkillSummary_NeuralODE + 1e-3)\n      #df_test$g_Skill_Dec[df_test$g_Skill_Dec<0]<-0\n      \n      library(scales) # Required for trans_format and math_format\n      p1 <- {ggplot(df_test, aes(x = nSamplesTrain_Decoder)) +\n        geom_smooth(aes(y = g_Skill_Node, color = \"Hybrid (NeuralODE)\", fill = \"Hybrid (NeuralODE)\"), \n                    method = \"lm\", formula = y ~ log(x), alpha = 0.15) +\n        geom_smooth(aes(y = g_Skill_Dec, color = \"Decoder-Only\", fill = \"Decoder-Only\"), \n                    method = \"lm\", formula = y ~ log(x), alpha = 0.15) +\n        \n        # 1. Scientific notation for x-axis (10^x)\n        scale_x_log10(\n          labels = scales::trans_format(\"log10\", scales::math_format(10^.x))\n        ) +\n        \n        # 2. Unify legend: 'name' must be identical for both scales to merge them\n        scale_color_manual(\n          name = NULL, \n          values = c(\"Hybrid (NeuralODE)\" = \"#e41a1c\", \"Decoder-Only\" = \"#377eb8\")\n        ) +\n        scale_fill_manual(\n          name = NULL, \n          values = c(\"Hybrid (NeuralODE)\" = \"#e41a1c\", \"Decoder-Only\" = \"#377eb8\")\n        ) +\n        labs(title = \"Data Efficiency\",\n             y = \"Stabilized Skill -log(1-S)\", \n             x = \"Training Samples\") + # \"log10\" removed from label as the ticks now show it explicitly\n        \n        theme_minimal(base_size = 14, base_line_size = 1) + \n        theme(legend.position = \"bottom\",panel.grid = element_blank() )}\n      p1\n      ggsave(sprintf(\"%s/MarginalDataScaling_%s.pdf\", SaveFolder, FiguresTag), p1, width = 7, height = 6)\n      \n      # -------------------------------------------------------------------------\n      # FIG 2: THE ENDOGENEITY PARADOX (The Robustness Test)\n      # Hypothesis: Stronger feedback (Endogeneity) lowers Baseline RSS (task gets 'easier'),\n      # but Decoder skill stagnates relative to Hybrid (Gap grows/sustains).\n      # -------------------------------------------------------------------------\n      if(\"c_endogeneous_Decoder\" %in% names(df_test)){\n        # Aggregate for clear trend lines\n     ",
    "   agg_endo <- df_test %>% group_by(c_endogeneous_Decoder) %>%\n          summarise(\n            BaseRSS = median(RSSBaselineSummary_Decoder, na.rm=T),\n            SkillGap = median(SkillSummary_NeuralODE - SkillSummary_Decoder, na.rm=T)\n          )\n        \n        # Scale factor for dual axis\n        coeff <- max(agg_endo$SkillGap) / max(agg_endo$BaseRSS)\n        \n        p2 <- ggplot(agg_endo, aes(x = c_endogeneous_Decoder)) +\n          geom_line(aes(y = BaseRSS * coeff, linetype = \"Baseline Difficulty (RSS)\"), color = \"gray50\", size = 1.2) +\n          geom_line(aes(y = SkillGap, color = \"Hybrid Advantage (Gap)\"), size = 1.5) +\n          scale_y_continuous(name = \"Hybrid Skill Advantage (Gap)\",\n                             sec.axis = sec_axis(~./coeff, name = \"Baseline RSS (Lower = 'Easier')\")) +\n          scale_color_manual(values = c(\"Hybrid Advantage (Gap)\" = \"#e41a1c\")) +\n          labs(title = \"2. The Endogeneity Paradox\",\n               subtitle = \"As feedback strengthens (x), the task becomes 'easier' (RSS drops),\\nyet the Hybrid's advantage persists or grows.\",\n               x = \"Endogeneity Strength (Feedback)\") +\n          theme_minimal(base_size = 14) + theme(legend.position = \"bottom\")\n        \n        ggsave(sprintf(\"%s/Insight2_Endogeneity_%s.pdf\", SaveFolder, FiguresTag), p2, width = 7, height = 6)\n      }\n      \n      # -------------------------------------------------------------------------\n      # FIG 3: REGIME ROBUSTNESS MAP (The Guardrails Test)\n      # Hypothesis: Hybrid wins most consistently in the \"Danger Zone\": \n      # High Endogeneity (Strong Feedback) + Sparse Data.\n      # -------------------------------------------------------------------------\n      if(\"c_endogeneous_Decoder\" %in% names(df_test)){\n        df_test$Win <- df_test$SkillSummary_NeuralODE > df_test$SkillSummary_Decoder\n        \n        # Bin if continuous, or use raw if grid\n        agg_map <- df_test %>%