  `ResultsGet/SuperLModel_GetAnalytics_Real.R` = paste0(
    "# Content of SuperLModel_GetAnalytics_Real.R\nif( !SimMode ){\n    print(\"Starting SuperLModel_GetAnalytics_Real.R\")\n    ndm_plot_log_series_safe <- utils::getFromNamespace(\".ndm_plot_log_series_safe\", \"ndm\")\n    # get out-of-sample results\n    #try(plot(rank(na.omit(in_loss_vec))), T) ; \n    #try(points(smooth.spline(rank(na.omit(in_loss_vec))),type = \"l\",lwd=3), T) \n  \n    # reset iterator and do analysis \n    gc(); py_gc$collect()\n    TFDatasetIterator_inference <- reticulate::as_iterator( TFDataset_inference )\n    inference_batch_dims <- function(batch_l){\n      if(\"try-error\" %in% class(batch_l) || is.null(batch_l) || length(batch_l) == 0L){\n        return(integer())\n      }\n      try(vapply(batch_l, function(l_){ as.integer(np$array(l_$shape)[[1]]) }, integer(1)), TRUE)\n    }\n    sl_dat <- c();ok_<-F; ok_counter_ <- 0; while(!ok_){ # !ok_ means do a batch\n          ok_counter_ <- ok_counter_ + 1\n          batch_l <- try(reticulate::iter_next( TFDatasetIterator_inference ), T) \n          \n          # reasons not to go on \n          if( \"try-error\" %in% class(batch_l) | is.null(batch_l) ){ ok_ <- T }\n          if( !ok_ ){\n            batch_dims <- inference_batch_dims(batch_l)\n            if(\"try-error\" %in% class(batch_dims) || length(batch_dims) == 0L || batch_dims[[1]] == 0L){\n              ok_ <- T\n            }\n            if(!ok_ && any(batch_dims != batch_dims[[1]])){\n              print2(\"Skipping malformed inference batch in GetAnalytics_Real.R...\")\n              ok_ <- T\n            }\n            if(!ok_){\n              batch_l <- TFConst2JAXArray( batch_l )\n            }\n          }\n          \n          # if going in do this\n          if(!ok_){\n          print2(sprintf(\"GetAnalytics_Real [@ sgd iter: %s, analytics iter: %s]\", i, ok_counter_))\n          #plot(as.matrix(batch_l$XPred_Mask[1,,])[,100],as.matrix(batch_l$XPred[1,,])[,100])\n          #input_df_red_full[input_df_red_full$location_id %in% loc_id & input_df_red_full$time_id %in% time_id,]\n          if(!(\"try-error\" %in% class(batch_l))){\n            #if(!is.null(batch_l) & !all(batch_l$is_null_indicator) & (length(batch_l_prior)>0)){\n            #if(!is.null(batch_l)  & (length(batch_l_prior)>0)){\n            #if(place_counter__ == 1 & time_counter__ == 1 & outSampCounter == 1){\n            {\n                # lapply(unlist(batch2package(batch_l)), function(l_){paste0(l_$shape)})\n                 add_pred_all <- replicate(5,list(try(GetPred_inference(\n                                    ModelList, batch2package(batch_l),\n                                    #ModelList, batch2package(batch_l_train),\n                                    state, PriorList, PolicyList,\n                                    GetPredSaveAtInfo_default,\n                                    ndm_runtime_data_to_device(jax$random$split(JaxKey(999L), batch_l$XPred$shape[[1]])))[[1]],T)))\n                                    #jax$random$split(JaxKey(999L), batch_l_train$XPred$shape[[1]]))[[1]],T)))\n                 add_pred_all <- add_pred_all[!(unlist(lapply(add_pred_all,class)) %in% 'try-error')]\n                 plot( np$array(add_pred_all[[1]]$y_mu)[,,1], \n                       np$array(batch_l$YTrue_out)[,,1],\n                       main = sprintf(\"Just1 at %s [Cor: %.3f]\",ok_counter_,\n                               cor(c(np$array(add_pred_all[[1]]$y_mu)[,,1]),\n                                   c(np$array(batch_l$YTrue_out)[,,1]))));abline(a=0,b=1)\n                 # plot( np$array(add_pred_all[[1]]$y_mu)[,,1], np$array(batch_l_train$YTrue_out)[,,1]);abline(a=0,b=1)\n                 # add_pred_all[[1]]$y_mu$shape\n                 # batch_l$XPred$shape\n                 # batch_l$XPred_mask\n                 # batch_l$XPred$mean(axis = 0L:1L)\n  \n                # analyze time dependent parameters\n                at_t <- try(colMeans(do.call(rbind,lapply(add_pred_all,function(zer){\n                                        c(ExtractBetaDraw(zer$ODEParamsSampList)$TSDraw) }))),T)\n                beta_hat_at_t <- try(colMeans(do.call(rbind,lapply(add_pred_all,function(zer){c(ExtractBetaDraw(zer$ODEParamsSampList)$BetaDraw)}))),T)\n                s_average <- try(colMeans(do.call(rbind,lapply(add_pred_all,function(zer){c(np$asanyarray(zer$ODEParamsSampList$s_l_samp) )}))),T)\n                e_average <- try(colMeans(do.call(rbind,lapply(add_pred_all,function(zer){c(np$asanyarray(zer$ODEParamsSampList$e_l_samp) )}))),T)\n                i_average <- try(colMeans(do.call(rbind,lapply(add_pred_all,function(zer){c(np$asanyarray(zer$ODEParamsSampList$i_l_samp) )}))),T)\n                r_average <- try(colMeans(do.call(rbind,lapply(add_pred_all,function(zer){c(np$asanyarray(zer$ODEParamsSampList$r_l_samp) )}))),T)\n  \n                add_sd_all <- colMeans(do.call(rbind,lapply(add_pred_all,function(zer){np$asanyarray(zer$y_sigma) })))\n                #if(mean(abs(add_sd_all)) < 0.01){browser() }\n                # plot(  sort(  input_df_red_full[input_df_red_full$location_id %in% loc_id,]$time_id ) )\n                # plot(  sort(  input_df_red_full[input_df_red_full$location_id %in% place_pool,]$time_id ) )\n                \n                #mean(input_df_red_in$time_id %in% input_df_red_full$time_id)\n                if(!UseShortOutcomes){ \n                  add_sd_past <- t(add_sd_all[c(1:abs(maxTimesPast))])\n                  add_sd_out <- t(add_sd_all[-c(1:abs(maxTimesPast))])\n                }\n                if(UseShortOutcomes){ \n                  add_sd_past <- t(add_sd_all); add_sd_out <- t(add_sd_all)\n                }\n  \n                # obtain posterior predicted mean\n                add_pred_all_reduced <- Reduce(`+`,\n                                               lapply(add_pred_all, \n                                                      function(l_){np$asanyarray(l_$y_mu)[,,1] })) / \n                                                 len",
    "gth(add_pred_all)\n                add_pred_all_reduced[add_pred_all_reduced<0] <- 0\n  \n                if(UseShortOutcomes){ \n                  add_pred_past <- (add_pred_all_reduced)\n                  add_pred_out <- (add_pred_all_reduced)\n                }\n                if(!UseShortOutcomes){ \n                  add_pred_past <- (add_pred_all_reduced[,c(1:abs(maxTimesPast))])\n                  add_pred_out <- (add_pred_all_reduced[,-c(1:abs(maxTimesPast))])\n                }\n  \n                # subset truth (no need to change subsetting here for short outcomes [using YTrue])\n                add_true_prior <- (np$asanyarray(batch_l$YTrue)[,c(1:abs(maxTimesPast)),])\n                add_true_prior_mask <- (np$asanyarray(batch_l$YTrue_mask)[,c(1:abs(maxTimesPast)),])\n                \n                add_true_out <- (np$asanyarray(batch_l$YTrue)[,-c(1:abs(maxTimesPast)),])\n                # max(abs(add_true_out - np$asanyarray(batch_l$YTrue_out)[,,1])) # sanity 0 value \n                add_true_out_mask <- (np$asanyarray(batch_l$YTrue_mask)[,-c(1:abs(maxTimesPast)),])\n                add_true_prior[add_true_prior_mask == 0] <- NA\n                add_true_out[add_true_out_mask == 0] <- NA\n                \n                if(length(dim(add_true_out)) > 2 & tail(dim(add_true_out),1)>1){ add_true_out <- add_true_out[,,1] }\n                if(length(dim(add_true_prior)) > 2 & tail(dim(add_true_prior),1)>1){ add_true_prior <- add_true_prior[,,1] }\n                # View(add_true_out[,,1])\n                # View(add_true_out_mask[,,1])\n  \n                # barplot\n                #par(mfrow = c(1,1))\n                #seir_ <- c(s_average,e_average,i_average,r_average)\n                #names(seir_) <- c(\"S[0]\",\"E[0]\",\"I[0]\",\"R[0]\")\n                #barplot(seir_ , add = F, density = 0.3, horiz  = F)\n  \n                # beta plot\n                #try(plot(at_t , beta_hat_at_t,type = \"b\",xlab=\"Time (t) in Times\"),T)\n              }\n              if(\"try-error\" %in% class(add_true_prior)){\n                add_true_prior <- add_true_out\n                add_true_prior[] <- NA\n              }\n              # par(mfrow=c(1,1));plot(x_<-c(add_true_out), y_<-c(add_pred_out));abline(a=0,b=1); print(cor(x_,y_, use = \"pairwise.complete\"))\n              colnames(add_pred_out) <- c(paste(\"Pred_l\",1:ncol(add_pred_out),sep=\"\"))\n              colnames(add_true_out) <- c(paste(\"Truth_l\",1:ncol(add_true_out),sep=\"\"))\n              colnames(add_true_prior) <- c(paste(\"PreviousSequenceTruth_l\",1:ncol(add_true_prior),sep=\"\"))\n              \n              # depreciate PredBase\n              add_pred_out_baseline <- add_pred_out\n              #add_pred_out_baseline[] <- add_true_prior[length(add_true_prior)]\n              add_pred_out_baseline[] <- NA\n              colnames(add_pred_out_baseline) <- gsub(colnames(add_pred_out_baseline),\n                                                   pattern = \"Pred\", replace = \"PredBase\")\n            \n              # jnp$mean(jnp$array(batch_l$XPred),axis = 0L:1L)\n              # jnp$std(jnp$array(batch_l$XPred),axis = 0L:1L)\n              plot(add_true_out, add_pred_out, main=sprintf(\"%s [Cor: %.3f]\",ok_counter_, LastOutCor <- cor(c(add_true_out),c(add_pred_out)))); abline(a=0,b=1)\n              \n              # combine results \n              sl_dat <- rbind(sl_dat, cbind(\"location_id\" = np$array(batch_l$location_id_numeric),\n                                         \"time_anchor_id\" = np$array(batch_l$time_id_numeric),#[!batch_l$is_null_indicator],\n                                         cbind(add_true_out,\n                                               add_pred_out,\n                                               add_pred_out_baseline,\n                                               add_true_prior) ) )\n              # plot(f2n(sl_dat[,\"Truth_l8\"]), f2n(sl_dat[,\"Pred_l8\"]));abline(a=0,b=1)\n              # plot(f2n(sl_dat[,\"Truth_l8\"]), f2n(sl_dat[,\"Truth_l1\"]));abline(a=0,b=1)\n          print2(sprintf(\"Skill sanity: %.3f\",\n              (Skill8SanityCheck <- 1 - (sum(( f2n(sl_dat[,\"Truth_l8\"]) - f2n(sl_dat[,\"Pred_l8\"]) )^2)+0.01)/\n                  ( sum(( f2n(sl_dat[,\"Truth_l8\"]) - f2n(sl_dat[,\"Truth_l1\"]) )^2) +0.01))))\n          }\n        }\n    }\n  \n    sl_dat <- eval(parse(text = sprintf('cbind(sl_dat,\n                    %s,\n                    \"modelingStrategy_name\" = modelingStrategyNameKey,\n                    \"nSGD\" = nSGD_model,\n                    \"nSGDPolicy\" = get0(\"nSGDPolicy\", inherits = TRUE, ifnotfound = NA_character_),\n                    \"nSGDAnchorMaxSamplesTrain\" = get0(\"nSGDAnchorMaxSamplesTrain\", inherits = TRUE, ifnotfound = NA_integer_),\n                    \"nSGDAnchorScope\" = get0(\"nSGDAnchorScope\", inherits = TRUE, ifnotfound = NA_character_),\n                    \"nSGDAnchorBatch\" = get0(\"nSGDAnchorBatch\", inherits = TRUE, ifnotfound = NA_integer_),\n                    \"nBatch\" = nBatch,\n                    \"maxTimesPast\" = maxTimesPast, # past context\n                    \"evaluationTime\" = evaluationTime,\n                    \"evaluationMethod\" = evaluationMethod,\n                    \"OUTER_ITERATION\" = OUTER_ITERATION,\n                    \"i_in_sgd\" = i,\n                    \"te_total\" = te_total, \n                    \"te_grads\" = te_grads, \n                    \"nTrainingSamplesSeen\" = i*nBatch, \n                    \"Skill8SanityCheck\" = Skill8SanityCheck, \n                    \"atEpoch\" = i*nBatch/nSamplesTrain, \n                    \"nParamsModel\" = nParamsModel, \n                    \"maxInSampleTime_id\" = max( input_df_red_in$time_id ),\n                    \"model_id\" = rlang::hash(modelingStrategyNameKey) )',\n                      paste(paste(\"'\",names(unlist(RealEntry)), \"'='\", unlist(RealEntry),\"'\", sep=\"\"),collapse=\",\")\n                      ) )",
    ")\n    sl_dat <- as.data.frame( sl_dat )\n    sl_dat$time_anchor_id <- unlist( sl_dat$time_anchor_id )\n    #plot(abs(f2n(sl_dat$PredBase_l6) - f2n(sl_dat$Truth_l6)), abs(f2n(sl_dat$Pred_l6) - f2n(sl_dat$Truth_l6))); abline(a=0,b=1)\n    #plot(abs(f2n(sl_dat$PredBase_l12) - f2n(sl_dat$Truth_l12)), abs(f2n(sl_dat$Pred_l12) - f2n(sl_dat$Truth_l12))); abline(a=0,b=1)\n\n    #summary(abs(f2n(sl_dat$PredBase_l4) - f2n(sl_dat$Truth_l4)))\n    #summary(abs(f2n(sl_dat$Pred_l4) - f2n(sl_dat$Truth_l4)))\n\n    #summary(abs(f2n(sl_dat$PredBase_l6) - f2n(sl_dat$Truth_l6)))\n    #summary(abs(f2n(sl_dat$Pred_l6) - f2n(sl_dat$Truth_l6)))\n\n    #summary(abs(f2n(sl_dat$PredBase_l12) - f2n(sl_dat$Truth_l12)))\n    #summary(abs(f2n(sl_dat$Pred_l12) - f2n(sl_dat$Truth_l12)))\n\n    #np$array(ModelList[[1]][[3]][[1]])\n    #np$array(ModelList[[1]][[3]][[2]])\n    #plot( predict(prcomp(np$array(ModelList[[1]][[3]][[1]])))[,1:2])\n    #plot( predict(prcomp(np$array(ModelList[[1]][[3]][[2]])))[,1:2])\n    #tapply(truth_df_red$location_id_numeric,truth_df_red$location_id_numeric,unique)\n\n    #  write loss fig for debugging (note: files are re-written)\n    pdf(file.path(\n      HolderFolder,\n      sprintf(\"diagnostics_%s_EvalTime%s_IsPretraining%s_OuterKey%s.pdf\",\n              rlang::hash(modelingStrategyNameKey),\n              evaluationTime,\n              IsPretraining,\n              OUTER_ITERATION)\n    ), height = 10, width = 5)\n    {\n    par(mfrow=c(2,1 + is.na(COMMAND_ARG_INPUT) ))\n    loss_obs <- na.omit(in_loss_vec)\n    grad_obs <- na.omit(grad_norm_vec)\n    ndm_plot_log_series_safe(loss_obs, main = \"Loss\")\n    if(length(loss_obs) > 0L){ plot(rank(loss_obs), log = \"\") } else { plot.new() }\n    ndm_plot_log_series_safe(grad_obs, main = \"Gradients\")\n    if(is.na(COMMAND_ARG_INPUT)){\n      tmp555 <- as.matrix(tmp555);try(plot(tmp555[1,],ylim = c(0,max(c(tmp555[1:10,]))),type = 'l',main=\"Y-hat\"),T)\n      for(i3 in 2:10){ try(points(tmp555[i3,],type = 'l',col = \"black\", lwd = 2, lty = 1),T) }\n    }\n    }\n    dev.off(); par(mfrow = c(1,1))\n    \n    # save results \n    data.table::fwrite(\n      as.matrix(sl_dat),\n      file = as.character(file.path(\n        HolderFolder,\n        sprintf(\"predicted_df_out_%s_EvalTime%s_IsPretraining%s_TrainIter%sof%s_OuterIter%s.csv\",\n                rlang::hash(modelingStrategyNameKey),\n                evaluationTime,\n                IsPretraining,\n                i,\n                nSGD_model,\n                OUTER_ITERATION)\n      ))\n    )\n    print(\"Done with SuperLModel_GetAnalytics_Real.R\")\n}\n\n# load(file = \"./tmp_input_df_red_full.Rdata\");\n# full sample\n#place_pool <- sample(unique(input_df_red_out$location_id[input_df_red_out$location_id %in% input_df_red_in$location_id]))\n\n# partial sample\n# place_pool <- sample(unique(input_df_red_out$location_id[input_df_red_out$location_id %in% input_df_red_in$location_id]), 50)\n# place_counter__ <- 0; for(loc_id in place_pool){\n# out of sample targets - how to  gen the input data for the base learners?\n#for(time_iter in time_iter_pool <- times_out){"
  ),
  `ResultsGet/SuperLModel_GetAnalytics_Sim.R` = paste0(
    "# Content of SuperLModel_GetAnalytics_Sim.R\nif(SimMode == T){\n  print(\"Starting SuperLModel_GetAnalytics_Sim.R\")\n  ndm_plot_log_series_safe <- utils::getFromNamespace(\".ndm_plot_log_series_safe\", \"ndm\")\n  analytics_truth_matrix <- function(x, name, nrow_expected, ncol_expected){\n    arr <- np$array(x)\n    dims <- dim(arr)\n    if(length(dims) == 3L && dims[[2]] == 1L){\n      arr <- arr[,1,]\n      dims <- dim(arr)\n    }\n    if(length(dims) == 2L && dims[[1]] == nrow_expected && dims[[2]] == ncol_expected){\n      return(arr)\n    }\n    stop(\n      sprintf(\n        \"Expected `%s` to resolve to a [%s x %s] batch matrix; got [%s]\",\n        name,\n        nrow_expected,\n        ncol_expected,\n        paste(dims, collapse = \" x \")\n      )\n    )\n  }\n  analytics_truth_vector <- function(x, name, nrow_expected){\n    arr <- np$array(x)\n    dims <- dim(arr)\n    if(length(dims) == 3L && dims[[2]] == 1L && dims[[3]] == 1L){\n      arr <- arr[,1,1]\n    } else if(length(dims) == 2L && dims[[2]] == 1L){\n      arr <- arr[,1]\n    }\n    arr <- as.numeric(arr)\n    if(length(arr) == nrow_expected){\n      return(arr)\n    }\n    stop(\n      sprintf(\n        \"Expected `%s` to resolve to a length-%s batch vector; got [%s]\",\n        name,\n        nrow_expected,\n        paste(dims, collapse = \" x \")\n      )\n    )\n  }\n  res_list <- replicate({list()}, n = nMonteEval)\n  for(nj in 1:nMonteEval){\n  print2( sprintf(\"nj %s of %s in GetAnalytics_Sim.R\", nj, nMonteEval  )) \n  #GetPredSaveAtInfo_inference <- list(jnp$array(tmp_ <- nTimesTotal-nTimesLookahead+nTimesLookValidation),\n  #GetPredSaveAtInfo_inference <- list(jnp$array(tmp_ <- nTimesLookValidationInference),\n  GetPredSaveAtInfo_inference <- list(tmp_ <- nTimesLookValidationInference,\n                                      diffrax$SaveAt(ts = jnp$array(  0L:(tmp_-1L) )))\n  ok_<-F; ok_counter_ <- 0; while(!ok_){\n    ok_counter_ <- ok_counter_ + 1\n    batch_l <- try(reticulate::iter_next( TFDatasetIterator_inference ), T) \n    if(\"try-error\" %in% class(batch_l)){ batch_l <- reticulate::iter_next( TFDatasetIterator_inference <- reticulate::as_iterator( TFDataset_inference )  )  }\n    if(length(batch_l)[[1]] == 0){ batch_l <- reticulate::iter_next( TFDatasetIterator_inference <- reticulate::as_iterator( TFDataset_inference )  )  }\n    if( np$array(batch_l[[1]]$shape)[[1]] != nBatch | is.null(batch_l) ){  \n      TFDatasetIterator_inference <- reticulate::as_iterator( TFDataset_inference ) \n    }\n    if( any(unlist(lapply(batch_l, function(l_){ np$array(l_$shape)[[1]] } ) ) != nBatch) ){  \n      badshape2_ctr <- 0; badshape2 <- T; while(badshape2){ \n        print2(\"Resetting type: bad shape (2) in GetAnalytics_Sim.R\")\n        badshape2_ctr <- badshape2_ctr + 1; if(badshape2_ctr > 100){stop(\"Too many bad shape (2)'s in GetAnalytics_Sim.R\")}\n        batch_l <- reticulate::iter_next(TFDatasetIterator_inference <- reticulate::as_iterator(TFDataset_inference))\n        badshape2 <- any(unlist(lapply(batch_l, function(l_){ np$array(l_$shape)[[1]] } ) ) != nBatch)  \n      }\n    }\n    batch_l <- TFConst2JAXArray( batch_l )\n    if(ok_counter_ > 100){ stop(\"Problem in SuperLModel_GetAnalytics_Sim.R\") }\n    if(!\"try-error\" %in% class(batch_l)){ ok_ <- T }\n  }\n  pred_l <- replicate(10,list(GetPred_inference(ModelList,\n                                                batch2package(batch_l),\n                                                state,\n                                                PriorList,\n                                                PolicyList,\n                                                GetPredSaveAtInfo_inference,\n                                                ndm_runtime_data_to_device(jax$random$split(JaxKey(as.integer(3L+runif(1,1,10000))),nBatch)) )[[1]]))\n  pred_l_mean <- lapply(pred_l,function(zer){  np$asanyarray( zer$y_mu )  })\n  pred_l_mean_full <- pred_l_mean <- 1/length(pred_l_mean) * Reduce(\"+\",pred_l_mean)\n  out_y_indices <- (1:ncol(pred_l_mean))[ !1:ncol(pred_l_mean) %in% 1:nTimesPast]\n  #pred_l_mean <- pred_l_mean[,out_y_indices <- (ncol(pred_l_mean) - nTimesLookahead+1):ncol(pred_l_mean),1]\n  #pred_l_mean <- pred_l_mean[,out_y_indices <- (1:ncol(pred_l_mean))[ !1:ncol(pred_l_mean) %in% 1:nTimesPast],1]\n  pred_l_mean <- pred_l_mean_full[,,1]\n  pred_l_sd <- lapply(pred_l,function(zer){ np$asanyarray( zer$y_sigma )[,,1] })\n  pred_l_sd <- 1/length(pred_l_sd) * Reduce(\"+\",pred_l_sd)\n  #plot(pred_l_mean[sample(1:dim(pred_l_mean)[1],1),])\n\n  # analysis of means\n  #l_true <- np$asanyarray( batch_l$YTrue) [,out_y_indices,1]\n  l_true <- np$asanyarray( batch_l$YTrue_out )[,,1]\n  #l_true_full <- np$asanyarray( batch_l$YTrue) [,,1]\n  pred_l_baselineVal <- np$asanyarray( batch_l$YTrue ) [,(nTimesTotal - nTimesLookahead),1]\n  pred_l_baselineVal_mat <- matrix(1,nrow = nrow(pred_l_mean), \n                                   ncol=ncol(pred_l_mean)) * \n                                pred_l_baselineVal\n  LastOutCor <- cor(c(l_true),c(pred_l_mean))\n  # plot(c(l_true),c(pred_l_mean_full));abline(a=0,b=1)\n  \n  ##############################\n  # R-squared analysis\n  ##############################\n  {\n  ### with predicted values\n  RawR2 <- function(yhat,ytrue){ 1 - sum( (yhat-ytrue)^2) / sum((ytrue-mean(ytrue))^2) }\n  MedianWithinR2_Raw <- median( sapply(1:nrow(l_true),function(zer){\n    WithinR2 <- RawR2(c(pred_l_mean[zer,]),l_true[zer,])\n  }) )\n  MedianWithinR2_Fit <- median( sapply(1:nrow(l_true),function(zer){\n    WithinR2 <- lm(c(l_true[zer,])~c(pred_l_mean[zer,]))\n    WithinR2 <- summary(WithinR2)$adj.r.squared\n  }) )\n  GlobalR2_Raw <- RawR2(c(pred_l_mean),c(l_true))\n  GlobalR2_Fit <- summary(lm(c(l_true)~c(pred_l_mean)))$adj.r.squared\n\n  ### compare against baseline\n  MedianWithinR2_Raw_baseline <- median( sapply(1:nrow(l_true),function(zer){\n    WithinR2 <- RawR2(\n      rep(pred_l_baselineVal[zer],times = ncol(l_true)),\n ",
    "     l_true[zer,])\n  }) )\n  MedianWithinR2_Fit_baseline <- median( sapply(1:nrow(l_true),function(zer){\n    WithinR2 <- lm(c(l_true[zer,])~1)\n    WithinR2 <- summary(WithinR2)$adj.r.squared\n  }) )\n  GlobalR2_Raw_baseline <- RawR2(c(pred_l_baselineVal_mat),c(l_true))\n  GlobalR2_Fit_baseline <- summary(lm(c(l_true)~c(pred_l_baselineVal_mat)))$adj.r.squared\n\n  FNorm_Raw <- mean(sqrt((c(pred_l_mean) - c(l_true))^2))\n  FNorm_Rel <- mean(sqrt((c(pred_l_mean) - c(l_true))^2)) / mean(sqrt(l_true^2))\n  FNorm_Raw_baseline <- mean(sqrt((c(pred_l_baselineVal_mat) - c(l_true))^2))\n  FNorm_Rel_baseline <- FNorm_Raw_baseline / mean(sqrt(l_true^2))\n\n  # agg norm\n  AggNorm_Raw <- mean(sqrt((rowSums(pred_l_mean) - rowSums(l_true))^2))\n  AggNorm_Rel <- mean(sqrt((rowSums(pred_l_mean) - rowSums(l_true))^2)) / \n                                    mean(sqrt(rowSums(l_true)^2))\n  AggNorm_Raw_baseline <- mean(sqrt((rowSums(pred_l_baselineVal_mat) - rowSums(l_true))^2))\n  AggNorm_Rel_baseline <- AggNorm_Raw_baseline / mean(sqrt(rowSums(l_true)^2))\n\n  # Skill measure\n  #plot(l_true[rer<-sample(1:10,1),],ylim=c(0,max(l_true))); points(pred_l_mean[rer,],pch=\"^\")\n  #plot(l_true[1,]);plot(pred_l_mean[1,])\n  RSS_baseline <- apply( (pred_l_baselineVal_mat - l_true)^2, 2, function(zr){ return(mean(clipAt(zr))) } )\n  RSS_pred <- apply( (pred_l_mean - l_true)^2, 2, function(zr){ return(mean(clipAt(zr) )) } )\n  skill_vec <- 1 - (0.001+RSS_pred^0.5) / (0.001+RSS_baseline^0.5)\n  names(skill_vec) <- paste(\"SkillTime\",1:length(skill_vec), sep = \"\")\n  names(RSS_pred) <- paste(\"RSSPredTime\",1:length(skill_vec), sep = \"\")\n  names(RSS_baseline) <- paste(\"RSSBaselineTime\",1:length(skill_vec), sep = \"\")\n\n  sd_outcome <- median( apply(l_true,1,sd) )\n  }\n\n  ##############################\n  # analyze structural parameters\n  ##############################\n  init_s <- init_e <- init_i <- init_r <- init_hat <-\n    AbsDiff_init <- KLDiv_init <- sigma_hat <- gamma_hat <-\n    AbsDiff_gamma <- RelAbsDiff_gamma <- AbsDiff_sigma <- RelAbsDiff_sigma <- NA\n  beta_hat <- beta_MedianWithinR2_Fit <- beta_MedianWithinR2_Raw <- beta_true <- NA;\n  beta_GlobalR2_Raw <- beta_GlobalR2_Fit <- beta_FNorm_Rel <- beta_FNorm_Raw <- beta_AggNorm_Rel <- beta_AggNorm_Raw <- NA\n  if(ModelType != \"DecoderOnly\"){\n    init_true_mat <- analytics_truth_matrix(\n      batch_l$init_true,\n      name = \"init_true\",\n      nrow_expected = nrow(pred_l_mean),\n      ncol_expected = 4L\n    )\n    gamma_true_vec <- analytics_truth_vector(\n      batch_l$gamma_true,\n      name = \"gamma_true\",\n      nrow_expected = nrow(pred_l_mean)\n    )\n    sigma_true_vec <- analytics_truth_vector(\n      batch_l$sigma_true,\n      name = \"sigma_true\",\n      nrow_expected = nrow(pred_l_mean)\n    )\n\n    # initial values\n    init_s <- colMeans(do.call(rbind,lapply(pred_l,function(zer){np$asanyarray( zer$ODEParamsSampList$s_l_samp) })))\n    init_e <- colMeans(do.call(rbind,lapply(pred_l,function(zer){np$asanyarray( zer$ODEParamsSampList$e_l_samp) })))\n    init_i <- colMeans(do.call(rbind,lapply(pred_l,function(zer){np$asanyarray( zer$ODEParamsSampList$i_l_samp) })))\n    init_r <- colMeans(do.call(rbind,lapply(pred_l,function(zer){np$asanyarray( zer$ODEParamsSampList$r_l_samp) })))\n    init_hat <- cbind((init_s),(init_e),(init_i),(init_r))\n    AbsDiff_init <- median(rowSums( abs(init_hat - init_true_mat )))\n    KLDiv_init <- median( rowSums(  init_true_mat * (log(init_hat) - log(init_true_mat) ) ))\n\n    sigma_hat <- colMeans(do.call(rbind,lapply(pred_l,function(zer){np$asanyarray( zer$ODEParamsSampList$sigma_samp) })))\n    gamma_hat <- colMeans(do.call(rbind,lapply(pred_l,function(zer){np$asanyarray( zer$ODEParamsSampList$gamma_samp) })))\n\n    AbsDiff_gamma <- median(  abs( gamma_true_vec - gamma_hat) )\n    RelAbsDiff_gamma <- median(  abs( gamma_true_vec - gamma_hat)/gamma_true_vec)\n\n    AbsDiff_sigma <- median(  abs( sigma_true_vec - sigma_hat) )\n    RelAbsDiff_sigma <- median(  abs( sigma_true_vec - sigma_hat)/sigma_true_vec)\n\n    ### beta analysis\n    if(ModelType != \"DecoderOnly\"){ \n      beta_hat <- lapply(pred_l, function(l_){ ExtractBetaDraw(l_$ODEParamsSampList)$BetaDraw })\n      beta_hat <- 1/length(beta_hat) * Reduce(\"+\",beta_hat)\n    }\n    if(T == F){ \n      beta_true <- t( apply(np$array(batch_l$inv_beta_true),1,function(zer){\n         #np$asanyarray( SoftPlus( zer[[1]]$evaluate(jnp$array(1.:max(out_y_indices),dtype=jnp$float64)) ) )\n          #zer \n          zer[1:max(out_y_indices)]\n      }) )\n      beta_MedianWithinR2_Raw <- median( sapply(1:nrow(beta_true),function(zer){\n        WithinR2 <- RawR2(c(beta_hat[zer,]),beta_true[zer,])\n      }) )\n      beta_MedianWithinR2_Fit <- median( sapply(1:nrow(beta_true),function(zer){\n        WithinR2 <- lm(c(beta_true[zer,])~c(beta_hat[zer,]))\n        WithinR2 <- summary(WithinR2)$adj.r.squared }) )\n      \n      beta_GlobalR2_Raw <- RawR2(c(beta_hat),c(beta_true))\n      beta_GlobalR2_Fit <- summary(lm(c(beta_true)~c(beta_hat)))$adj.r.squared\n  \n      beta_FNorm_Raw <- mean(sqrt((c(beta_hat) - c(beta_true))^2))\n      beta_FNorm_Rel <- mean(sqrt((c(beta_hat) - c(beta_true))^2)) / mean(sqrt(beta_true^2))\n  \n      beta_AggNorm_Raw <- mean(sqrt((rowSums(beta_hat) - rowSums(beta_true))^2))\n      beta_AggNorm_Rel <- mean(sqrt((rowSums(beta_hat) - rowSums(beta_true))^2)) / mean(sqrt(rowSums(beta_true)^2))\n    }\n  }\n\n  ##############################\n  # policy eval metrics\n  ##############################\n  {\n  # data gen part  is indexed to: t0 = 0, t1 = NTimeSteps_SIM,\n  # model part  is indexed to: t0 = 0, t1 = nTimesTotal,\n  InterpolatorBasis_ <- rep(0.1, times = NTimeSteps_SIM+1)\n  #ShiftFactor <- min( np$array( NTimeSteps_SIM - nTimesPast )  )\n  ShiftFactor <- min( np$array( 0 + nTimesPast )  )\n\n  startIntervention <- max( np$array( ShiftFactor )  ) + 2L\n  IndicatorBasis_un <- rep(0, NTimeSteps_SIM+1)\n  Indicato",
    "rBasis_un[-c(1:startIntervention)] <- 1\n  # IndicatorBasis_un[-c(1:ShiftFactor)][1:nTimesTotal]\n  # PolicyList_GetBatch_unnatural[[1]]$evaluate(jnp$array((startIntervention-1):startIntervention))\n  PolicyList_GetBatch_natural <- list(\n    \"ComputeScenario\" = F,\n\n    # scenario (defines the smooth shift trajectory in the policy from the previous state)\n    \"Scenario\" = jnp$array(InterpolatorBasis_[1:NTimeSteps_SIM])\n  )\n\n  PolicyList_GetBatch_unnatural <- list(\n    \"ComputeScenario\" = T,\n\n    # scenario (defines the smooth shift trajectory in the policy from the previous state)\n    \"Scenario\" = jnp$array(InterpolatorBasis_[1:NTimeSteps_SIM])\n    )\n\n  model_policy_ts <- jnp$array(as.numeric(0:(nTimesTotal-1L)))\n  model_policy_scenario <- jnp$array(InterpolatorBasis_[-c(1:ShiftFactor)][1:(nTimesTotal+0)])\n  PolicyList_Model_natural <- list(\n    # policy indicator\n    diffrax$LinearInterpolation(\n      model_policy_ts,\n      jnp$array(rep(0, nTimesTotal + 0))\n    ),\n\n    # scenario (defines the smooth shift trajectory in the policy from the previous state)\n    diffrax$LinearInterpolation(\n      model_policy_ts,\n      model_policy_scenario\n    )\n  )\n\n  PolicyList_Model_unnatural <- list(\n    # policy indicator\n    diffrax$LinearInterpolation(\n      model_policy_ts,\n      jnp$array(IndicatorBasis_un[-c(1:ShiftFactor)][1:(nTimesTotal+0)])\n    ),\n\n    # scenario (defines the smooth shift trajectory in the policy from the previous state)\n    diffrax$LinearInterpolation(\n      model_policy_ts,\n      model_policy_scenario\n    )\n  )\n  }\n\n  \n  # get factual and counterfactual data\n  PolicyScenarioSkillRes <- PolicyScenarioSkillBaselineRes <- NULL; nCounterfactuals <- 0; policy_eval_failed <- FALSE; while( nCounterfactuals < 2 ){\n    nCounterfactuals <- nCounterfactuals + 1\n    counterf_ <- ai(runif(1,1,10000))\n    ok_<-F; ok_counter_ <- 0; while(!ok_){\n      ok_counter_ <- ok_counter_ + 1\n      set.seed(PolicyEvalSeed <- (12456L + counterf_)); batch_l_natural <- try(GetBatch(\n                                      nBatch = nBatch, \n                                      INPUT_REF_DAT = input_df_red_in,\n                                      PolicyList = PolicyList_GetBatch_natural,\n                                      nTimes = NTimeSteps_SIM,\n                                      nTimesLook = nTimesLookValidation), T)\n      set.seed(PolicyEvalSeed);batch_l_unnatural <- try(GetBatch(nBatch = nBatch,  \n                                      INPUT_REF_DAT = input_df_red_in,\n                                      nTimes = NTimeSteps_SIM,\n                                      nTimesLook = nTimesLookValidation,\n                                      PolicyList = PolicyList_GetBatch_unnatural), T) \n                                      #PolicyList = PolicyList_GetBatch_natural),T) # for debugging\n      if(ok_counter_ > 100){\n        warning(\"Skipping policy scenario analytics because natural/counterfactual batches could not be generated\")\n        policy_eval_failed <- TRUE\n        break\n      }\n      if(!\"try-error\" %in% class(batch_l_natural) & !\"try-error\" %in% class(batch_l_unnatural) ){ ok_ <- T }\n    }\n    if(policy_eval_failed){ break }\n    {\n      # get factual and counterfactual predictions\n      # note: t is differnt in meaning for getting data and for modeling\n      hat_y_natural <- GetPred_inference(\n        ModelList, batch2package(batch_l_natural),\n        state, PriorList, PolicyList_Model_natural,\n        GetPredSaveAtInfo_inference,\n        ndm_runtime_data_to_device(jax$random$split(JaxKey(9L+counterf_), nBatch)))[[1]]\n      hat_y_unnatural <- GetPred_inference(\n        ModelList, batch2package(batch_l_unnatural),\n        state, PriorList, PolicyList_Model_unnatural,\n        GetPredSaveAtInfo_inference,\n        ndm_runtime_data_to_device(jax$random$split(JaxKey(9L), nBatch)))[[1]]\n\n      # skill baseline -predicting unnatural outcomes with natural outcomes\n      NUM <- (0.001+colMeans(abs(np$array( batch_l_unnatural$YTrue_out )[,,1] -\n                            np$array( batch_l_natural$YTrue_out )[,,1])))\n      DENOM <- (0.001+colMeans(abs( np$array( batch_l_unnatural$YTrue_out )[,,1] -\n                            matrix(np$array( batch_l_natural$YTrue_out )[,1,1],\n                                   ncol = ncol(np$array( batch_l_natural$YTrue_out )),\n                                   nrow = nrow(np$array( batch_l_natural$YTrue_out )),byrow=F)   )) )\n      PolicyScenarioSkill_baseline <- NUM / DENOM\n\n      # skill - predicting unnatural outcomes using natural predictions\n      NUM <- (0.001+colMeans(abs(np$array( batch_l_unnatural$YTrue_out )[,,1] -#out_y_indices\n                            np$array( hat_y_unnatural$y_mu )[,,1] )))\n                            #np$array( hat_y_unnatural$y_mu )[,out_y_indices,1] )))\n      DENOM <- (0.001+colMeans(abs(np$array( batch_l_unnatural$YTrue_out )[,,1] -\n                                np$array( hat_y_natural$y_mu )[,,1])) )\n                                     #np$array( hat_y_natural$y_mu )[,out_y_indices,1])) )\n      PolicyScenarioSkill <- NUM  / DENOM\n\n      names(PolicyScenarioSkill) <- paste(\"PolicySkill\", 1:length(PolicyScenarioSkill), sep=\"\")\n      names(PolicyScenarioSkill_baseline) <- paste(\"PolicySkillBaseline\", 1:length(PolicyScenarioSkill_baseline), sep=\"\")\n      PolicyScenarioSkillRes <- rbind(PolicyScenarioSkillRes,PolicyScenarioSkill)\n      PolicyScenarioSkillBaselineRes <- rbind(PolicyScenarioSkillBaselineRes,PolicyScenarioSkill_baseline)\n\n      if(PolicyPlot <- F){\n        # sample an observation\n        i_ <- sample(1:batch_l_natural$YTrue[[1]]$shape[[1]], 1)\n\n        # data-generation outcome scenario checks\n        par(mfrow=c(2,2))\n        plot( np$array( batch_l_natural$YTrue[[1]] )[i_,,1],main = \"Disease Outcomes\", ylim = c(0, max( c(np$array( batch_l_unnatural$YTrue[[1]] )[i_,,1] ,np$array",
    "( batch_l_natural$YTrue[[1]] )[i_,,1]))))\n        #abline(v =  batch_l_natural$YTrue[[1]]$shape[[2]] - nTimesLookahead-1,col=\"red\")\n        points( np$array( batch_l_unnatural$YTrue[[1]] )[i_,,1] , col = \"gray\",pch = 3)\n\n        # data-generation policy scenario checks\n        plot( tmp <- np$array( batch_l_natural$YTrue[[1]] )[i_,,2], main = \"Policy Stringency\", ylim = summary(c(np$array( batch_l_unnatural$YTrue[[1]] )[i_,,2], np$array( batch_l_natural$YTrue[[1]] )[i_,,2]) )[c(1,6)])\n        #abline(v =  batch_l_natural$YTrue[[1]]$shape[[2]] - nTimesLookahead,col=\"red\")\n        points( np$array( batch_l_unnatural$YTrue[[1]] )[i_,,2],  col = \"gray\", pch = 3)\n\n        # data-generation beta scenario checks\n        plot( np$array( SoftPlus(batch_l_natural$inv_beta_true))[i_,1:length(tmp)], main = \"Beta\", ylim = summary(c(np$array( SoftPlus(batch_l_natural$inv_beta_true) )[i_,], np$array( SoftPlus(batch_l_unnatural$inv_beta_true) )[i_,]) )[c(1,6)])\n        #abline(v =  batch_l_natural$YTrue[[1]]$shape[[2]] - nTimesLookahead,col=\"red\")\n        points( np$array( SoftPlus(batch_l_unnatural$inv_beta_true) )[i_,1:length(tmp)],  col = \"gray\", pch = 3)\n\n\n        # prediction scenario outcome checks\n        plot( ( np$array( hat_y_natural$y_mu )[i_,,1]), main=\"Pred Truths\",ylim = summary(c(( np$array( hat_y_natural$y_mu )[i_,,1]),c(np$array( hat_y_unnatural$y_mu )[i_,,1])))[c(1,6)])\n        points( np$array( hat_y_unnatural$y_mu )[i_,,1],  col = \"gray\", pch = 3)\n        # plot(np$array( hat_y_natural$y_mu )[i_,,1] - np$array( hat_y_unnatural$y_mu )[i_,,1])\n\n        # prediction scenario policy checks\n        plot( ( np$array( hat_y_natural$y_mu )[i_,,2]), main=\"Pred Policies\", ylim = c(-10, 10))\n        points( np$array( hat_y_unnatural$y_mu )[i_,,2],  col = \"gray\", pch = 3)\n        PolicyList_Model_unnatural[[1]]$evaluate(jnp$array(0:(nTimesTotal-1L)))\n        par(mfrow=c(1,1))\n\n        # prediction beta policy checks\n        #plot( ( np$array( hat_y_natural$ODEParamsSampList$diff_eq_sol_ys.Neural1 )[i_,,LocalNeuralEmbedDim+1]), ylim = summary( np$array( hat_y_natural$ODEParamsSampList$diff_eq_sol_ys.Neural1 )[i_,,LocalNeuralEmbedDim+1])[c(1,6)])\n        #points( np$array( hat_y_unnatural$ODEParamsSampList$diff_eq_sol_ys.Neural1 )[i_,,LocalNeuralEmbedDim+1],  col = \"gray\", pch = 3)\n\n        # analysis\n        # plot( np$array(hat_y_natural$ODEParamsSampList$diff_eq_sol_ys.Neural1)[i_,,LocalNeuralEmbedDim+1] )\n        # hist( apply(np$array(hat_y_natural$ODEParamsSampList$diff_eq_sol_ys.Neural1)[,,LocalNeuralEmbedDim+1], 1,  function(zer){mean(diff(zer))}), xlab = \"\"); abline(v = 0, lwd = 2)\n      }\n    }\n  }\n  if(is.null(PolicyScenarioSkillRes) || is.null(PolicyScenarioSkillBaselineRes)){\n    PolicyScenarioSkillRes <- rep(NA_real_, nTimesLookValidationInference)\n    names(PolicyScenarioSkillRes) <- paste(\"PolicySkill\", seq_len(nTimesLookValidationInference), sep=\"\")\n    PolicyScenarioSkillBaselineRes <- rep(NA_real_, nTimesLookValidationInference)\n    names(PolicyScenarioSkillBaselineRes) <- paste(\"PolicySkillBaseline\", seq_len(nTimesLookValidationInference), sep=\"\")\n  } else {\n    PolicyScenarioSkillRes <- colMeans(PolicyScenarioSkillRes)\n    PolicyScenarioSkillBaselineRes <- colMeans(PolicyScenarioSkillBaselineRes)\n  }\n  rm_list_ <- c(\"batch_l_unnatural\",\"batch_l_natural\",\"hat_y_natural\",\"hat_y_unnatural\")\n  rm_list_ <- rm_list_[vapply(rm_list_, exists, logical(1), inherits = FALSE)]\n  if(length(rm_list_) > 0L){ rm(list = rm_list_) }\n\n  ##############################\n  # setup save variable names\n  ##############################\n  if(nj == 1){\n    SaveQuantityNames <- c(outcome2 <- c(\"MedianWithinR2_Raw\",\"MedianWithinR2_Fit\",\n                                         \"GlobalR2_Raw\",\"GlobalR2_Fit\",\n                                         \"FNorm_Raw\",\"FNorm_Rel\",\n                                         \"AggNorm_Raw\",\"AggNorm_Rel\"),\n                           paste(outcome2, \"_baseline\",sep = \"\"))\n    SaveQuantityNames <- c(SaveQuantityNames,\"beta_MedianWithinR2_Raw\",\n                  \"beta_MedianWithinR2_Fit\",\n                  \"beta_AggNorm_Raw\",\n                  \"beta_AggNorm_Rel\",\n                  \"beta_FNorm_Raw\",\n                  \"sd_outcome\",\n                  \"beta_FNorm_Rel\",\n                  \"beta_GlobalR2_Raw\",\n                  \"beta_GlobalR2_Fit\")\n    SaveQuantityNames <- c(SaveQuantityNames,\n                           \"AbsDiff_init\",\"KLDiv_init\",\n                           \"AbsDiff_gamma\",\"RelAbsDiff_gamma\",\n                           \"AbsDiff_sigma\",\"RelAbsDiff_sigma\")\n  }\n\n  tmp <- sapply(SaveQuantityNames,function(ze){\n    list(eval(parse(text = sprintf(\"c('%s' = eval(parse(text = %s)))\",ze,ze))))\n  })\n  names(tmp) <- NULL\n  res_list[[nj]] <- c(do.call(c,tmp), skill_vec, RSS_pred, RSS_baseline, PolicyScenarioSkillRes, PolicyScenarioSkillBaselineRes)\n  }\n  \n  #  write loss fig for debugging \n  pdf(file.path(HolderFolder, sprintf(\"diagnostics%s.pdf\", af)), height = 10, width = 5)\n  {\n  par(mfrow=c(2,2))\n  loss_obs <- na.omit(in_loss_vec)\n  grad_obs <- na.omit(grad_norm_vec)\n  ndm_plot_log_series_safe(loss_obs, main = \"Loss\")\n  if(length(loss_obs) > 0L){ plot(rank(loss_obs), log = \"\") } else { plot.new() }\n  ndm_plot_log_series_safe(grad_obs, main = \"Gradients\")\n  dev.off()\n  }\n  par(mfrow = c(1,1))\n  \n  \n  # --- Skill sanity check (aggregate RMSE vs. persistence baseline) ---\n  {\n    eps <- 1e-3\n    skill_horizon <- max(1L, min(8L, ncol(pred_l_mean)))\n    rmse_pred <- sqrt(mean(clipAt((c(pred_l_mean[,skill_horizon]) - c(l_true[,skill_horizon]))^2), na.rm = TRUE))\n    rmse_base <- sqrt(mean(clipAt((c(pred_l_baselineVal_mat[,skill_horizon]) - c(l_true[,skill_horizon]))^2), na.rm = TRUE))\n    Skill8SanityCheck <- 1 - (eps + rmse_pred) / (eps + rmse_base)\n    print2(sprintf(\"Skil",
    "l sanity: %.3f\", Skill8SanityCheck))\n  }\n  \n  # save results to disk \n  res_vec <- t(c(\"sim_index\" = af,\n                 \"i_in_sgd\" = i,\n                 \"nTrainingSamplesSeen\" = i*nBatch,\n                 \"atEpoch\" = i*nBatch/nSamplesTrain, \n                 \"nSGD\" = nSGD_model,\n                 \"nSGDPolicy\" = get0(\"nSGDPolicy\", inherits = TRUE, ifnotfound = NA_character_),\n                 \"nSGDAnchorMaxSamplesTrain\" = get0(\"nSGDAnchorMaxSamplesTrain\", inherits = TRUE, ifnotfound = NA_integer_),\n                 \"nSGDAnchorScope\" = get0(\"nSGDAnchorScope\", inherits = TRUE, ifnotfound = NA_character_),\n                 \"nSGDAnchorBatch\" = get0(\"nSGDAnchorBatch\", inherits = TRUE, ifnotfound = NA_integer_),\n                 \"nParamsModel\" = nParamsModel,\n                 \"te_total\" = te_total, \n                 \"te_grads\" = te_grads, \n                 unlist(SimEntry),\n                 colMeans(do.call(rbind,res_list))))\n  print(sprintf(\"WRITING af of %s\", af))\n  data.table::fwrite(file = file.path(HolderFolder, sprintf(\"res%s_i%s.csv\", af, i)), res_vec)\n  save.image(file = file.path(HolderFolder, sprintf(\"res%s_i%s.Rdata\", af, i)))\n  print(\"Done with SuperLModel_GetAnalytics_Sim.R\")\n}"
  ),
  `ResultsGet/SuperLModel_GetAnalytics.R` = "# Content of SuperLModel_GetAnalytics.R\n# Analytics for real\nndm_source_extracted(\"ResultsGet/SuperLModel_GetAnalytics_Real.R\")\n\n# Analytics for simulation\nndm_source_extracted(\"ResultsGet/SuperLModel_GetAnalytics_Sim.R\")",
  `SetupData/MultiDiseaseRuns/SuperL_UniversalDataReader.R` = paste0(
    "# Content of UniversalDataReader.R\nif(dataFormat == \"Tycho\"){\n  ReSaveRawData <- TRUE\n  if( ReSaveRawData ){\n    \n    # CDC (1982 onwards; reports); \n    # CDC wonder (1993 onwards); \n    # 1950-1981 (public health reports)\n    \n    # load in tycho data \n    options(error = NULL)\n    #dataloc <- \"./Data/MultiDiseaseRuns/TB-USA/US.427099000/\"\n    dataloc <- \"./Data/MultiDiseaseRuns/TB-USA-2\"\n    csvs_ <- (csvs_ <- list.files(dataloc))[grepl(csvs_,pattern=\"\\\\.csv\")]\n    \n    raw_input_data <- c()\n    for(csv_ in csvs_){\n      raw_input_data <- rbind(raw_input_data,\n                              read.csv(sprintf(\"%s/%s\",dataloc, csv_)))\n    }\n    \n    # define period duration (in weeks)\n    raw_input_data$PeriodDurationWeeks <- difftime(as.Date(raw_input_data$PeriodEndDate),\n                    as.Date(raw_input_data$PeriodStartDate),units = \"weeks\")\n    # View(raw_input_data[order(raw_input_data$PeriodDurationWeeks,decreasing=T),])\n    # plot(raw_input_data$PeriodDurationWeeks)\n    \n    library(dplyr); library(lubridate)\n    # load in population data \n    pop_file <- \"./Data/MultiDiseaseRuns/population_state_year.csv\"\n    #pop_url  <- \"https://raw.githubusercontent.com/JoshData/historical-state-population-csv/primary/historical_state_population_by_year.csv\"\n    #if (!file.exists(pop_file)) {\n    #  dir.create(dirname(pop_file), recursive = TRUE, showWarnings = FALSE)\n    #  download.file(pop_url, destfile = pop_file, quiet = TRUE, mode = \"wb\")\n    #}\n    population_df <- read.csv(pop_file, col.names = c(\"state_abbr\", \"year\", \"population\")) %>%\n      dplyr::mutate(state_abbr = as.character(state_abbr),\n                    year        = as.integer(year),\n                    population  = as.numeric(population))\n    \n    ## ---- UNIVERSAL TRANSLATION:  Project\u202FTycho  -------------------------------\n    raw_input_data\n    tycho_df <- raw_input_data %>%\n      mutate(\n        location_id   = Admin1ISO,              # \u201CUS\u2011WI\u201D\n        location_name = Admin1Name,             # \u201CWISCONSIN\u201D\n        location_id_numeric =\n          as.integer(factor(location_id, levels = sort(unique(location_id)))) - 1L,\n        date_start = as.Date(PeriodStartDate),\n        week_id    = as.integer(difftime(date_start,\n                                         min(date_start, na.rm = TRUE),\n                                         units = \"weeks\")),\n        time_id  = week_id,\n        targetTime_id = time_id,\n        year       = lubridate::year(date_start),     # <\u2011\u2011 NEW\n        CountValue = as.numeric(CountValue)\n      ) %>%\n      select(location_id, location_id_numeric, location_name,\n             date_start, year, time_id, targetTime_id, CountValue) %>%\n      arrange(location_id, time_id)\n    \n    ## Pull the two\u2011letter state abbrev from the Admin1ISO code\n    tycho_df <- tycho_df %>% \n                  mutate(state_abbr = sub(\"^US-\", \"\", location_id))\n    \n    ## Merge and fill the (rare) missing values using last\u2011observation\u2011carried\u2011forward\n    tycho_df <- tycho_df %>%\n      left_join(population_df, by = c(\"state_abbr\", \"year\")) %>%\n      group_by(state_abbr) %>%\n      tidyr::fill(population, .direction = \"down\") %>%   # if early years missing\n      tidyr::fill(population, .direction = \"up\") %>%     # if late years missing\n      ungroup()\n    \n    ## Convert counts to fractions (and an interpretable per\u2011100\u202Fk rate)\n    tycho_df <- tycho_df %>%\n      mutate(\n        CountFraction   = CountValue / population,\n        CasesPerPop    = CountFraction * 1e5\n      )\n    \n    # Hand off the population\u2011standardised series to downstream code\n    truth_df_red  <- tycho_df %>%\n      select(location_id, location_id_numeric, location_name,\n             time_id, targetTime_id,\n             CountFraction, CasesPerPop)            %>%\n      rename(CountValue = CountFraction)\n    \n    # sanity check -- should be \u2264\u202F1 everywhere (real outbreaks rarely hit that, obviously)\n    summary(truth_df_red$CasesPerPop)\n    \n    # Quick visual check for one state\n    if(FALSE){\n      #View(truth_df_red[truth_df_red$location_name==\"TEXAS\",])\n      #View(raw_input_data[raw_input_data$Admin1Name==\"TEXAS\",])\n      #STATE <- \"TEXAS\"\n      STATE <- \"WISCONSIN\"\n      \n      sort(tapply(raw_input_data$PeriodDurationWeeks, raw_input_data$Admin1Name,sd))\n      \n      plot(table(as.Date(raw_input_data$PeriodStartDate)))\n      plot(as.Date(raw_input_data[raw_input_data$Admin1Name==STATE,]$PeriodStartDate),\n           raw_input_data[raw_input_data$Admin1Name==STATE,]$CountValue)\n      \n      library(ggplot2)\n      filter(truth_df_red, location_name == STATE) |>\n        ggplot(aes(x = time_id, y = CountValue * 1e5)) +\n        geom_line() +\n        labs(y = \"TB cases per 100,000\", x = \"Epi-time index\")\n    }\n    \n    # Collapse duplicates\n    truth_df_red <- truth_df_red %>%\n      group_by(location_id, location_id_numeric, location_name,\n               time_id, targetTime_id) %>%\n      summarise(CountValue = sum(CountValue, na.rm = TRUE), .groups = \"drop\")\n    \n    # write to disk\n    if(ReSaveRawData){\n      write.csv(truth_df_red, \"./Data/MultiDiseaseRuns/Tycho_processed.csv\", row.names = FALSE)\n    }\n  }\n  \n  # 3. Expose universally\u2011named objects expected by the downstream scripts -----\n  truth_df_red           <- truth_df_red           # Targets (Y)\n  input_df_red           <- truth_df_red           # Past values as covariates (X)\n  true_value_names       <- \"CountValue\"\n  all_true_value_names   <- true_value_names   # keeps interface identical to multi\u2011outcome cases\n  \n  # Autoregressive covariate set \u2013 past observations only\n  dataInputs_colnames_past    <- \"CountValue\"\n\n  # Union needed later in normalisation step\n  dataInputs_colnames         <- c(dataInputs_colname",
    "s_past,\n                                   dataInputs_colnames_future)\n  \n  # How many outcomes are we forecasting?\n  nOutcomes <- length(true_value_names)\n  nPlaces <- length(unique(truth_df_red$location_id))\n}\nif(dataFormat == \"WHO\"){\n  my_data <- read.csv('./Data/MultiDiseaseRuns/DiseasePool/incidence-of-tuberculosis-sdgs.csv')\n  \n  library(dplyr); library(lubridate); library(tidyr)\n  who_df <- my_data %>%\n    # Standardize column names\n    dplyr::rename(\n      location_name = Entity,\n      location_id   = Code,\n      year          = Year,\n      CasesPerPop  = Estimated.incidence.of.all.forms.of.tuberculosis\n    ) %>%\n    # Types & minimal cleaning\n    mutate(\n      year         = as.integer(year),\n      CasesPerPop = as.numeric(CasesPerPop),\n      # Fill blank/NA codes (e.g., continents/regions) with the entity name\n      location_id  = dplyr::if_else(is.na(location_id) | trimws(location_id) == \"\",\n                                    location_name, location_id),\n      date_start   = as.Date(paste0(year, \"-01-01\")),\n      theweek_id      = as.integer(difftime(date_start,\n                                         min(date_start, na.rm = TRUE),\n                                         units = \"weeks\")),\n      time_id      = (year - min(my_data$Year)), # 0 indexed \n      targetTime_id = time_id,\n      # Convert WHO incidence (per pop size) to a population fraction to match Tycho\n      CountFraction = CasesPerPop / 1e3\n    ) %>%\n    mutate(\n      location_id_numeric =\n        as.integer(factor(location_id, levels = sort(unique(location_id)))) - 1L\n    ) %>%\n    arrange(location_id, time_id)\n  \n  ## If you want *countries only* and to drop regional aggregates, uncomment:\n  ## who_df <- who_df %>% dplyr::filter(nchar(location_id) == 3)\n  \n  # Hand off in the same shape Tycho produces\n  truth_df_red <- who_df %>%\n    select(location_id, location_id_numeric, location_name,\n           time_id, targetTime_id, CountFraction) %>%\n    rename(CountValue = CountFraction) %>%\n    group_by(location_id, location_id_numeric, location_name,\n             time_id, targetTime_id) %>%\n    summarise(CountValue = sum(CountValue, na.rm = TRUE), .groups = \"drop\")\n  \n  # Optional write (kept parallel to Tycho branch)\n  # write.csv(truth_df_red, \"./Data/MultiDiseaseRuns/WHO_processed.csv\", row.names = FALSE)\n  \n  # drop \n  truth_df_red <- truth_df_red[!is.na(truth_df_red$CountValue),]\n  \n  # 3. Expose universally\u2011named objects expected by the downstream scripts -----\n  truth_df_red         <- truth_df_red           # Targets (Y)\n  input_df_red         <- truth_df_red           # Past values as covariates (X)\n  truth_df_red$Covariate1 <- truth_df_red$CountValue\n  true_value_names     <- \"CountValue\"\n  all_true_value_names <- true_value_names\n  \n  # Autoregressive covariate set \u2013 past observations only\n  dataInputs_colnames_future <- NULL \n  dataInputs_colnames_past <- c(\"CountValue\",\"Covariate1\")\n  # Union needed later in normalisation step\n  dataInputs_colnames <- c(dataInputs_colnames_past, dataInputs_colnames_future)\n  outcome_metric <- \"CountValue\"\n  \n  # How many outcomes are we forecasting?\n  nOutcomes <- length(true_value_names)\n  nPlaces <- length(unique(truth_df_red$location_id))\n  \n  hist(truth_df_red[outcome_metric][[1]])\n\n  # check for NAs\n  colMeans(truth_df_red[,dataInputs_colnames_past],na.rm=T)\n  colMeans(truth_df_red[,dataInputs_colnames_past],na.rm=T)\n  #head(truth_df_red)\n}\nif(dataFormat == \"IHME\"){\n  ihme_candidates <- c(\n    \"./Data/MultiDiseaseRuns/IHMEData/IHME-GBD_2021_DATA-ea2ad67b-1/IHME-GBD_2021_DATA-ea2ad67b-1.csv\",\n    \"./Data/MultiDiseaseRuns/DiseasePool/IHMEData/IHME-GBD_2021_DATA-ea2ad67b-1/IHME-GBD_2021_DATA-ea2ad67b-1.csv\"\n  )\n  ihme_file <- ihme_candidates[file.exists(ihme_candidates)][1]\n  if (is.na(ihme_file) || !nzchar(ihme_file)) {\n    stop(\n      \"IHME data file not found. Checked: \",\n      paste(ihme_candidates, collapse = \", \"),\n      call. = FALSE\n    )\n  }\n  my_data <- read.csv(ihme_file)\n  table(my_data$year); table(my_data$metric_name)\n  table(my_data$cause_name)\n  my_data <- my_data[which(my_data$sex_name==\"Both\" & \n                             my_data$metric_name == \"Rate\" & \n                             my_data$cause_name == \"HIV/AIDS and sexually transmitted infections\" & \n                             my_data$age_name == \"All ages\"),]\n  #View(my_data)\n  #head(my_data)\n  #hist(my_data$val)\n  #hist(my_data$upper)\n  \n  library(dplyr); library(lubridate); library(tidyr)\n  \n  ## ---- IHME \u2192 universal format ---------------------------------------------\n    # Choose a single measure: prefer Prevalence, else Incidence, else first available.\n  if (exists(\"desired_measure\")) {\n    my_data <- dplyr::filter(my_data, measure_name == desired_measure)\n  } else {\n    preferred_measures <- c(\"Prevalence\")\n    chosen_measure <- intersect(preferred_measures, unique(my_data$measure_name))\n    if (length(chosen_measure) == 0) chosen_measure <- unique(my_data$measure_name)[1]\n    my_data <- dplyr::filter(my_data, measure_name == chosen_measure[1])\n  }\n  \n  # Convert IHME metrics to a population fraction suitable for downstream use.\n  ihme_df <- my_data %>%\n    mutate(\n      year       = as.integer(year),\n      date_start = as.Date(paste0(year, \"-01-01\")),\n      CountFraction_tmp = dplyr::case_when(\n        # IHME \"Rate\" is per 100,000 population\n        metric_name == \"Rate\"    ~ as.numeric(val) / 1e5,\n        # IHME \"Percent\": robust to either 0\u20131 or 0\u2013100 encoding\n        metric_name == \"Percent\" ~ dplyr::if_else(as.numeric(val) > 1,\n                                                  as.numeric(val) / 100,\n                                                  as.numeric(val)),\n        TRUE                     ~ NA_real_\n      ),\n      # prefer \"Rate\" over \"Percent\" if both